"use client"

import type {
    BaseSyntheticEvent,
} from "react"
import { Button, ProgressBar, Spinner, Typography } from "@heroui/react"
import { useTranslations } from "next-intl"
import { Dropzone } from "@/components/blocks/form/Dropzone"

/** Max CV upload size (10MB), mirrored in the drop hint copy. */
const MAX_CV_BYTES = 10 * 1024 * 1024

/** Props for {@link CvSubmissionFields}. */
export interface CvSubmissionFieldsProps {
    /** Currently selected CV file, or `null`. */
    cv: File | null
    /** Validation error message for the `cv` field, if any. */
    cvError?: string
    /** Whether the wrapped react-hook-form form is currently submitting. */
    isSubmitting: boolean
    /** Sets the `cv` field value on the react-hook-form form. */
    onCvChange: (file: File | null) => void
    /** Fired on form submit — react-hook-form's wrapped `handleSubmit`. */
    onSubmit: (event?: BaseSyntheticEvent) => Promise<void>
    /** Whether the S3 upload step is in progress. */
    isUploading: boolean
    /** Whether the backend processing step is in progress. */
    isProcessing: boolean
    /** Upload progress percentage (0–100). */
    uploadProgress: number
    /** Name of the successfully uploaded file, or `null`. */
    uploadedFileName: string | null
    /** S3 key of the successfully uploaded file, or `null`. */
    uploadedS3Key: string | null
    /** Fired to trigger backend processing of the uploaded CV. */
    onProcess: () => void
}

/**
 * Inner field layout for the CV submission form: canonical {@link Dropzone}
 * (real drag-drop + token styling + inline error), progress bar, and the
 * upload/process buttons. Presentational — renders react-hook-form field state +
 * upload state, no business logic. All copy via the `cv.submission.*` namespace.
 * @param props - {@link CvSubmissionFieldsProps}
 */
export const CvSubmissionFields = ({
    cv,
    cvError,
    isSubmitting,
    onCvChange,
    onSubmit,
    isUploading,
    isProcessing,
    uploadProgress,
    uploadedFileName,
    uploadedS3Key,
    onProcess}: CvSubmissionFieldsProps) => {
    const t = useTranslations("cv.submission")

    return (
        <form onSubmit={onSubmit} className={"flex flex-col gap-3"}>
            <div className="flex flex-col gap-2">
                <Typography type="body-sm" weight="medium">{t("uploadLabel")}</Typography>
                <Dropzone
                    acceptedMimeTypes={["application/pdf"]}
                    maxSizeInBytes={MAX_CV_BYTES}
                    file={cv}
                    hint={t("dropHint")}
                    errorMessage={cvError}
                    onChange={onCvChange}
                />
                {uploadedFileName && uploadedS3Key ? (
                    <Typography type="body-sm" className="text-success-soft-foreground">
                        {t("uploadSuccess")}
                    </Typography>
                ) : null}
            </div>

            {isUploading ? (
                <div className="flex flex-col gap-2">
                    <div className="flex items-center justify-between">
                        <Typography type="body-sm" weight="medium">{t("uploadingCta")}</Typography>
                        <Typography type="body-sm" color="muted">{uploadProgress}%</Typography>
                    </div>
                    <ProgressBar
                        className="w-full"
                        maxValue={100}
                        minValue={0}
                        value={uploadProgress}
                    >
                        <ProgressBar.Track>
                            <ProgressBar.Fill />
                        </ProgressBar.Track>
                    </ProgressBar>
                </div>
            ) : null}

            <Button
                type="submit"
                isDisabled={isUploading || isProcessing || isSubmitting}
                fullWidth
                variant="primary"
            >
                {isUploading ? (
                    <>
                        <Spinner size="sm" />
                        {t("uploadingCta")}
                    </>
                ) : (
                    t("uploadCta")
                )}
            </Button>

            <Button
                type="button"
                isDisabled={
                    !uploadedFileName
                    || !uploadedS3Key
                    || isUploading
                    || isProcessing
                }
                fullWidth
                variant="secondary"
                onPress={onProcess}
            >
                {isProcessing ? (
                    <>
                        <Spinner size="sm" />
                        {t("processingCta")}
                    </>
                ) : (
                    t("processCta")
                )}
            </Button>
        </form>
    )
}

"use client"

import React from "react"
import { cn, Typography } from "@heroui/react"
import type { WithClassNames } from "@/modules/types/base/class-name"

/** Props for {@link ListRow}. */
export interface ListRowProps extends WithClassNames<undefined> {
    /**
     * Optional leading node rendered before the text column, kept at its
     * intrinsic size (icon or avatar). Does not shrink.
     */
    leading?: React.ReactNode
    /**
     * Primary line of the row. Rendered as medium-weight foreground text and
     * truncated to a single line when it overflows.
     */
    title: React.ReactNode
    /**
     * Optional secondary line shown beneath the title in muted, smaller text and
     * truncated to a single line.
     */
    subtitle?: React.ReactNode
    /**
     * Optional right-aligned metadata (chips / counts / timestamps) rendered
     * before the trailing node.
     */
    meta?: React.ReactNode
    /**
     * Optional far-right node, typically a chevron or inline action, rendered
     * after the meta content.
     */
    trailing?: React.ReactNode
    /**
     * When true, adds a bottom border so consecutive same-type rows read as a
     * separated list. Omit on the final row of a group.
     */
    divider?: boolean
    /**
     * Optional press handler. When provided (or {@link ListRowProps.href} is
     * set) the row becomes interactive with a hover surface and is keyboard /
     * screen-reader accessible.
     */
    onPress?: () => void
    /**
     * Optional link target. When provided the row renders as an anchor so the
     * whole row navigates on click.
     */
    href?: string
}

/**
 * Generic GitHub-style list row designed to live inside a
 * {@link import("@/components/blocks/cards/SectionCard").SectionCard}. Lays out an optional
 * leading icon/avatar, a title + optional subtitle text column, and a
 * right-aligned meta + trailing cluster. Purely presentational: text and
 * handlers arrive via props so the row stays store-free and reusable.
 *
 * @param props - {@link ListRowProps}
 */
export const ListRow = ({
    leading,
    title,
    subtitle,
    meta,
    trailing,
    divider = false,
    onPress,
    href,
    className,
}: ListRowProps) => {
    const isPressable = Boolean(onPress || href)

    const content = (
        <>
            {leading ? <div className="shrink-0">{leading}</div> : null}
            <div className="flex min-w-0 flex-col gap-0">
                <Typography type="body-sm" weight="medium" truncate>
                    {title}
                </Typography>
                {subtitle ? (
                    <Typography type="body-xs" color="muted" truncate>
                        {subtitle}
                    </Typography>
                ) : null}
            </div>
            {meta || trailing ? (
                <div className="ml-auto flex shrink-0 items-center gap-2">
                    {meta}
                    {trailing}
                </div>
            ) : null}
        </>
    )

    const baseClassName = cn(
        "flex min-w-0 items-center gap-3 py-2",
        divider && "border-b border-separator",
        isPressable &&
            "rounded-2xl transition-colors hover:bg-surface-secondary focus-visible:bg-surface-secondary focus-visible:outline-none",
        className,
    )

    if (href) {
        return (
            <a href={href} onClick={onPress} className={baseClassName}>
                {content}
            </a>
        )
    }

    if (onPress) {
        return (
            <div
                role="button"
                tabIndex={0}
                onClick={onPress}
                onKeyDown={(event) => {
                    if (event.key === "Enter" || event.key === " ") {
                        event.preventDefault()
                        onPress()
                    }
                }}
                className={cn(baseClassName, "cursor-pointer")}
            >
                {content}
            </div>
        )
    }

    return <div className={baseClassName}>{content}</div>
}

import React from "react"
import {
    ArrowRightIcon,
    CheckCircleIcon,
    CircleIcon,
    ClockIcon,
    LockIcon,
    PlayIcon,
    StackIcon,
    UsersIcon,
} from "@phosphor-icons/react"
import { AsyncContentEmpty, AsyncContentError } from "@/components/composites/async/AsyncContent"
import { SurfaceCardList, type SurfaceCardListItem } from "@/components/composites/cards/SurfaceCard"
import { HighlightChip } from "@/components/composites/chips/HighlightChip"
import { PageHeader } from "@/components/composites/layout/Page"
import { ProgressMeter } from "@/components/composites/stats/ProgressMeter"
import type { ComponentTypeWithSkeleton } from "@/components/frames/_slot"
import { Button } from "@/components/atoms/buttons/Button"
import { Typography } from "@/components/atoms/text/Typography"
import { Container } from "@/components/frames/Container"
import { StackH, StackV } from "@/components/frames/Stack"
import { DifficultyChip, type Difficulty } from "@/components/blocks/chips/DifficultyChip"
import { GithubTeamGate } from "@/components/blocks/auth/GithubTeamGate"
import { LearnBreadcrumb } from "@/components/blocks/learn/LearnBreadcrumb"
import { LearnNudges } from "@/components/blocks/learn/LearnNudges"
import { TrialConversionStrip } from "@/components/blocks/commerce/TrialConversionStrip"

/** One lesson row on the "keep going" path — leading state icon · title · minutes-read · difficulty + premium-lock. */
export interface CourseContentsLesson {
    /** Stable id (React key + reader deep-link target). */
    id: string
    /** Lesson title — the row's primary line. */
    title: string
    /** Already-localized "N min read" caption — the row's subtitle. */
    minutesReadText: string
    /** Where the viewer stands on this lesson: the highlighted next one, an already-read one, or untouched. */
    state: "active" | "read" | "unread"
    /** Difficulty tier (resolved from the raw string by the connected file); omitted → no difficulty chip. */
    difficulty?: Difficulty
    /** `true` → a premium lesson the trial viewer can't open yet → a trailing lock. */
    isPremium: boolean
    /** Open this lesson in the reader. */
    onPress: () => void
}

/** Catalog meta figures for the header chips — identity facts the progress stat line does NOT carry. */
export interface CourseContentsMeta {
    /** Chapter/module count. */
    moduleCount: number
    /** Already-formatted study-hours figure (e.g. `"~3"`). */
    hoursText: string
    /** Already-formatted learner count; omitted → the learners chip is skipped. */
    learnersText?: string
}

/** All display text, already localized by the connected {@link CourseContents}; a story passes i18n keys. */
export interface CourseContentsLabels {
    emptyTitle: string
    errorTitle: string
    retry: string
    /** Meta-chip labels. */
    metaModulesLabel: string
    metaHoursLabel: string
    metaLearnersLabel: string
    /** Continue-cluster eyebrow — the connected file picks capstone / continue / all-done. */
    eyebrow: string
    /** Primary resume-button label — the connected file picks capstone vs normal. */
    resumeButton: string
    /** Meter label. */
    completion: string
    /** Full "lessons · challenges" stat line — the connected file interpolates + joins it. */
    progressStat: string
    /** Keep-going kicker; the presentational file appends `· <module title>`. */
    keepGoing: string
    /** Premium-lock accessible name. */
    premiumLabel: string
}

/** Props for {@link _CourseContents} — presentational; all data resolved, no fetch/store/i18n. */
export interface CourseContentsProps {
    /** Async status, owned by the connected file. */
    isLoading?: boolean
    error?: unknown
    onRetry?: () => void
    /** `true` (after loading) → no outline → the empty state. */
    isEmpty?: boolean
    /** Course title — the page heading. */
    title: string
    /** One-line course description under the title. */
    description?: string
    /** Header catalog meta; omitted → the meta chip row is skipped. */
    meta?: CourseContentsMeta
    /** Present ONLY for a not-yet-enrolled learner (the connected file owns that gate) → the conversion strip renders. */
    trialStrip?: {
        courseId: string
        freeLessonsRemaining: number
    }
    /** Resume target's title; omitted → no continue title line. */
    resumeTitle?: string
    /** Open the resume target; omitted → no resume button (all done). */
    onResume?: () => void
    /** Overall completion percent (0-100) for the meter. */
    completionPercent: number
    /** The current module's title — the keep-going heading. */
    moduleTitle?: string
    /** The current module's lessons = the keep-going path. Empty → the path is skipped. */
    lessons: Array<CourseContentsLesson>
    labels: CourseContentsLabels
}

/** state → leading icon on the lesson row (the frame forces `size-5`). */
const STATE_ICON = {
    active: PlayIcon,
    read: CheckCircleIcon,
    unread: CircleIcon,
} as const

/**
 * Placeholder rows for the keep-going path while loading. ONE tree — the resting
 * state is the SAME `SurfaceCardList` shimmered, never a hand-mirrored copy that drifts.
 */
const SKELETON_LESSON_ROWS: Array<SurfaceCardListItem> = Array.from({ length: 4 }, (_unused, index) => ({
    key: `skeleton-lesson-${index}`,
    title: "Lesson",
    subtitle: "min read",
    leadingIcon: CircleIcon,
}))

/** Breadcrumb slot for the header — a connected child that self-fetches its crumbs (split.md). */
const BreadcrumbSlot: ComponentTypeWithSkeleton = () => <LearnBreadcrumb />

interface CourseContentsMetaChipsProps {
    meta: CourseContentsMeta
    labels: Pick<CourseContentsLabels, "metaModulesLabel" | "metaHoursLabel" | "metaLearnersLabel">
}

const CourseContentsMetaChips = ({ meta, labels }: CourseContentsMetaChipsProps) => (
    <StackH
        gap={3}
        items={[
            () => <HighlightChip icon={StackIcon} value={meta.moduleCount} label={labels.metaModulesLabel} />,
            () => <HighlightChip icon={ClockIcon} value={meta.hoursText} label={labels.metaHoursLabel} />,
            ...(meta.learnersText
                ? [() => <HighlightChip icon={UsersIcon} value={meta.learnersText!} label={labels.metaLearnersLabel} />]
                : []),
        ]}
    />
)

/**
 * Course-content home — the presentational half of {@link CourseContents}, composed on the
 * tier-correct storybook vocabulary (`Container` / `PageHeader` / `HighlightChip` / `ProgressMeter` /
 * `SurfaceCardList`). Layout: breadcrumb → header (title + description + catalog meta) → GitHub-team
 * warning → trial conversion strip (gated by the connected file) → continue cluster (eyebrow + resume
 * title + Resume button, one honest completion meter, the lessons·challenges stat line) → contextual
 * nudges → keep-going path (the current module's lessons as rows). The self-fetching children
 * (`GithubTeamGate` / `TrialConversionStrip` / `LearnNudges` / `LearnBreadcrumb`) are rendered as-is —
 * a presentational screen may render connected children (split.md). The connected `index.tsx` owns the
 * fetch and i18n.
 *
 * @param props - {@link CourseContentsProps}
 */
export const _CourseContents = ({
    isLoading = false,
    error,
    onRetry,
    isEmpty = false,
    title,
    description,
    meta,
    trialStrip,
    resumeTitle,
    onResume,
    completionPercent,
    moduleTitle,
    lessons,
    labels,
}: CourseContentsProps) => {
    const metaSlot: ComponentTypeWithSkeleton | undefined = meta
        ? () => <CourseContentsMetaChips meta={meta} labels={labels} />
        : undefined

    // Keep-going path rows — each lesson as a fixed SurfaceCardList row: leading state icon, title,
    // minutes-read subtitle, and a difficulty + premium-lock meta slot.
    const lessonRows: Array<SurfaceCardListItem> = lessons.map((lesson) => {
        const { difficulty, isPremium } = lesson
        const metaSlot = difficulty != null || isPremium
            ? () => (
                <StackH
                    gap={3}
                    items={[
                        ...(difficulty != null ? [() => <DifficultyChip difficulty={difficulty} />] : []),
                        ...(isPremium ? [() => (
                            <LockIcon
                                aria-label={labels.premiumLabel}
                                focusable="false"
                                className="size-5 text-muted"
                            />
                        )] : []),
                    ]}
                />
            )
            : undefined
        return {
            key: lesson.id,
            title: lesson.title,
            subtitle: lesson.minutesReadText,
            leadingIcon: STATE_ICON[lesson.state],
            leadingIconColor: lesson.state === "active" ? "accent" : lesson.state === "read" ? "success" : undefined,
            onPress: lesson.onPress,
            meta: metaSlot,
        }
    })

    // ONE tree — the resting state is this SAME spine with `isSkeleton` threaded into every
    // shimmer-capable part, never a hand-mirrored copy. `spine(true)` is the loading branch,
    // `spine(false)` the content branch; they cannot drift because they are the same code.
    const spine = (isSkeleton: boolean) => (
        <Container
            identity={{ tier: "page", component: "CourseContents" }}
            size="md"
            principle="center-measure"
            explain="Caps reading width so long copy does not stretch edge-to-edge across the viewport."
            body={() => (
                <StackV
                    gap={7}
                    principle="layout-split"
                    explain="Major layout split — not block-boundary, because this separates primary page regions rather than adjacent blocks."
                    items={[
                        // Header — its OWN tier, gap-10 (page band) from the content cluster below.
                        () => (
                            <PageHeader
                                breadcrumb={BreadcrumbSlot}
                                title={title}
                                description={description}
                                meta={metaSlot}
                                isSkeleton={isSkeleton}
                            />
                        ),
                        // Content cluster: GitHub-team warning · trial strip · continue · nudges · path.
                        // The connected children (GithubTeamGate · TrialConversionStrip · LearnNudges)
                        // own THEIR resting shape — they self-fetch and shimmer themselves.
                        () => (
                            <StackV
                                gap={6}
                                principle="block-boundary"
                                explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                                items={[
                                    () => <GithubTeamGate />,
                                    ...(trialStrip ? [() => (
                                        <TrialConversionStrip
                                            courseId={trialStrip.courseId}
                                            freeLessonsRemaining={trialStrip.freeLessonsRemaining}
                                        />
                                    )] : []),
                                    // Continue + progress — flat (no card face), the honest unified meter.
                                    () => (
                                        <StackV
                                            gap={4}
                                            principle="card-caption"
                                            explain="Holds caption text under card media so the caption stays attached to the image above it."
                                            items={[
                                                () => (
                                                    <StackH
                                                        align="start"
                                                        justify="between"
                                                        gap={4}
                                                        principle="content-row"
                                                        explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                        items={[
                                                            () => (
                                                                <StackV
                                                                    gap={1}
                                                                    classNames={["min-w-0"]}
                                                                    items={[
                                                                        () => <Typography size="xs" color="muted" isSkeleton={isSkeleton} text={labels.eyebrow} />,
                                                                        ...(isSkeleton || resumeTitle ? [() => (
                                                                            <Typography size="base" weight="semibold" truncate isSkeleton={isSkeleton} text={resumeTitle} />
                                                                        )] : []),
                                                                    ]}
                                                                />
                                                            ),
                                                            // Button carries no `isSkeleton` — a resting screen shows no CTA yet.
                                                            ...(!isSkeleton && onResume ? [() => (
                                                                <Button
                                                                    label={labels.resumeButton}
                                                                    variant="primary"
                                                                    size="lg"
                                                                    suffixIcon={ArrowRightIcon}
                                                                    iconSlide
                                                                    onPress={onResume}
                                                                    classNames={["shrink-0"]}
                                                                />
                                                            )] : []),
                                                        ]}
                                                    />
                                                ),
                                                () => (
                                                    <ProgressMeter
                                                        value={completionPercent}
                                                        max={100}
                                                        label={labels.completion}
                                                        showValue
                                                        isSkeleton={isSkeleton}
                                                    />
                                                ),
                                                () => <Typography size="xs" color="muted" isSkeleton={isSkeleton} text={labels.progressStat} />,
                                            ]}
                                        />
                                    ),
                                    // Contextual nudges — aids that orbit the spine; each self-hides at 0.
                                    () => <LearnNudges />,
                                    // Keep-going path — the current module's lessons (the full tree lives
                                    // in the left content-map rail, so the body never re-draws it).
                                    // While loading it shimmers the SAME list with placeholder rows.
                                    ...((isSkeleton || lessons.length > 0) ? [() => (
                                        <StackV
                                            gap={4}
                                            items={[
                                                () => (
                                                    <Typography
                                                        size="sm"
                                                        weight="semibold"
                                                        color="muted"
                                                        isSkeleton={isSkeleton}
                                                        text={`${labels.keepGoing} · ${moduleTitle ?? ""}`}
                                                    />
                                                ),
                                                () => <SurfaceCardList items={isSkeleton ? SKELETON_LESSON_ROWS : lessonRows} isSkeleton={isSkeleton} />,
                                            ]}
                                        />
                                    )] : []),
                                ]}
                            />
                        ),
                    ]}
                />
            )}
        />
    )

    // error → skeleton → empty → content (BLOCK-8): the empty and error surfaces are the shared
    // `AsyncContent*` frames dropped in as their own states; otherwise the ONE spine renders, with
    // `isLoading` flowing in as the co-located shimmer flag (loading-and-skeleton.md §6).
    const inner = error
        ? <AsyncContentError title={labels.errorTitle} onRetry={onRetry} retryLabel={labels.retry} />
        : (!isLoading && isEmpty)
            ? <AsyncContentEmpty title={labels.emptyTitle} />
            : spine(isLoading)

    return inner
}

"use client"

import React from "react"
import {
    CaretRightIcon,
} from "@phosphor-icons/react"
import {
    useTranslations,
} from "next-intl"
import _ from "lodash"
import { StatusChip } from "@/components/blocks/chips/StatusChip"
import { MarkdownContent } from "@/components/blocks/rendering/MarkdownContent"
import { CourseContentTier } from "@/modules/types/enums/course-content-tier"
import { type ModuleEntity } from "@/modules/types/entities/module"
import {
    AccordionTreeBody,
    AccordionTreeHeading,
    AccordionTreeItem,
    AccordionTreePanel,
    AccordionTreeTrigger,
} from "@/components/atoms/navigation/AccordionTree"
import { Typography } from "@/components/atoms/text/Typography"
import { Cluster } from "@/components/frames/Cluster"
import { StackH, StackV } from "@/components/frames/Stack"

/** Chip tone per learning tier (foundation → advanced reads easy → hard). */
const TIER_TONE: Record<CourseContentTier, "success" | "warning" | "danger"> = {
    [CourseContentTier.Foundation]: "success",
    [CourseContentTier.Intermediate]: "warning",
    [CourseContentTier.Advanced]: "danger",
}

/** Props for {@link ModuleAccordionItem}. */
export interface ModuleAccordionItemProps {
    /** The module to render as one accordion row (list-item data prop). */
    module: ModuleEntity
}

/**
 * One curriculum module as an accordion row: title + tier badge + premium lock in
 * the trigger; lesson/minute meta + description + free preview bullets in the
 * panel. List-item (rendered in a `.map`), so it takes the `module` data prop.
 *
 * @param props - {@link ModuleAccordionItemProps}
 */
export const ModuleAccordionItem = ({ module }: ModuleAccordionItemProps) => {
    const t = useTranslations()

    const contents = module.contents ?? []
    const minutes = contents.reduce((sum, content) => sum + (content.minutesRead ?? 0), 0)
    const lessonCount = module.numContents || contents.length
    const previews = _.cloneDeep(module.previewContents ?? []).sort(
        (a, b) => a.sortIndex - b.sortIndex,
    )
    const contentTier = module.contentTier

    return (
        <AccordionTreeItem aria-label={module.title}>
            <AccordionTreeHeading>
                <AccordionTreeTrigger>
                    <StackH gap={4} principle="content-row"
                        explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                        classNames={["min-w-0", "flex-1"]} justify="between" align="center" items={[
                            () => (
                                <Typography
                                    size="sm"
                                    weight="medium"
                                    truncate
                                    classNames={["min-w-0"]}
                                    text={module.title}
                                />
                            ),
                            () => (
                                <Cluster
                                    gap={3}
                                    principle="chip-row"
                                    explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                                    classNames={["shrink-0"]}
                                    items={[
                                        ...(contentTier ? [() => (
                                            <StatusChip tone={TIER_TONE[contentTier]}>
                                                {t(`courseLanding.tier.${contentTier}`)}
                                            </StatusChip>
                                        )] : []),
                                        ...(previews.length > 0 ? [() => (
                                            <StatusChip tone="neutral">
                                                {t("courseLanding.previewCount", { count: previews.length })}
                                            </StatusChip>
                                        )] : []),
                                    ]}
                                />
                            ),
                        ]} />
                </AccordionTreeTrigger>
            </AccordionTreeHeading>
            <AccordionTreePanel>
                <AccordionTreeBody>
                    <StackV gap={4} principle="card-caption"
                        explain="Holds caption text under card media so the caption stays attached to the image above it."
                        items={[
                            () => (
                                <Typography
                                    size="xs"
                                    color="muted"
                                    text={t("courseLanding.moduleMeta", { lessons: lessonCount, minutes })}
                                />
                            ),
                            () => (module.description ? (
                                <MarkdownContent markdown={module.description} />
                            ) : null),
                            () => (previews.length > 0 ? (
                                <StackV gap={2} principle="sibling-stack"
                                    explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                    items={previews.map((preview) => () => (
                                        <StackH key={preview.id} gap={3} principle="identity"
