"use client"

import React from "react"
import { Typography, cn } from "@heroui/react"
import { SpeakerHighIcon, SpeakerSlashIcon } from "@phosphor-icons/react"
import { SurfaceCard } from "@/components/composites/cards/SurfaceCard"
import { StackH, StackV } from "@/components/frames/Stack"
import type { MockInterviewPersona } from "../interviewPersona"

/** Props for {@link InterviewerPresence}. */
export interface InterviewerPresenceProps {
    /** The interviewer identity (face photo + name). */
    persona: MockInterviewPersona
    /** Whether the interviewer is currently "speaking" (a question is streaming in). */
    speaking: boolean
    /** Label shown next to the speaking pulse (e.g. "speaking"). */
    speakingLabel: string
    /** Whether the browser supports text-to-speech (hides the toggle when false). */
    ttsSupported: boolean
    /** Whether the interviewer reads questions aloud. */
    ttsEnabled: boolean
    /** Toggle spoken output. */
    onToggleTts: () => void
    /** aria-label for the mute toggle (when currently on). */
    muteLabel: string
    /** aria-label for the unmute toggle (when currently off). */
    unmuteLabel: string
    /** The question body (streaming markdown / current question / pending hint). Omit for a header-only presence (design thread renders turns separately). */
    children?: React.ReactNode
}

/** Props for {@link PulseBar}. */
interface PulseBarProps {
    /** Animation delay in milliseconds. */
    delayMs: number
    /** Tailwind height class for the bar. */
    heightClass: string
}

/** One animated bar of the "speaking" pulse. */
const PulseBar = ({ delayMs, heightClass }: PulseBarProps) => (
    <span
        className={cn("w-[3px] animate-pulse rounded-full bg-accent", heightClass)}
        style={{ animationDelay: `${delayMs}ms` }}
        aria-hidden
    />
)

/**
 * The interviewer's PRESENCE in the room — a monogram avatar + name + role, a
 * "speaking" pulse while a question streams in, and a speaker toggle for
 * text-to-speech. Optionally wraps the question body (`children`) below a
 * divider, turning the old faceless gray question box into "someone is
 * interviewing you". Header-only (no children) for the design thread, where
 * turns render as a separate chat below.
 *
 * @param props - {@link InterviewerPresenceProps}
 */
export const InterviewerPresence = ({
    persona,
    speaking,
    speakingLabel,
    ttsSupported,
    ttsEnabled,
    onToggleTts,
    muteLabel,
    unmuteLabel,
    children}: InterviewerPresenceProps) => {
    return (
        <div>
            <SurfaceCard
                padding={5}
                body={() => (
                    <>
                        <StackH
                            gap={4}
                            principle="content-row"
                            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                            justify="between"
                            classNames={["w-full"]}
                            items={[
                                () => (
                                    <StackH
                                        gap={4}
                                        classNames={["min-w-0", "flex-1"]}
                                        items={[
                                            () => (
                                                <img
                                                    src={persona.avatarSrc}
                                                    alt=""
                                                    className="size-10 shrink-0 rounded-full object-cover"
                                                    aria-hidden
                                                />
                                            ),
                                            () => (
                                                <StackV
                                                    gap={1}
                                                    principle="name-handle"
                                                    explain="Display name with handle — not title-subtitle, because the second line is an identity handle rather than a subtitle."
                                                    classNames={["min-w-0"]}
                                                    items={[
                                                        () => (
                                                            <StackH
                                                                gap={3}
                                                                principle="flex-action"
                                                                explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                                                                items={[
                                                                    () => (
                                                                        <Typography type="body-sm" weight="medium" className="truncate">
                                                                            {persona.name}
                                                                        </Typography>
                                                                    ),
                                                                    ...(speaking
                                                                        ? [() => (
                                                                            // Pulse + label at preserved 8px — no step-3 token fits icon-text (4px).
                                                                            <StackH
                                                                                gap={3}
                                                                                items={[
                                                                                    () => (
                                                                                        <span className="flex items-end gap-[2px]" aria-hidden>
                                                                                            <PulseBar delayMs={0} heightClass="h-2" />
                                                                                            <PulseBar delayMs={150} heightClass="h-3" />
                                                                                            <PulseBar delayMs={300} heightClass="h-1.5" />
                                                                                        </span>
                                                                                    ),
                                                                                    () => (
                                                                                        <Typography type="body-xs" className="text-accent-soft-foreground">
                                                                                            {speakingLabel}
                                                                                        </Typography>
                                                                                    ),
                                                                                ]}
                                                                            />
                                                                        )]
                                                                        : []),
                                                                ]}
                                                            />
                                                        ),
                                                        () => (
                                                            <Typography type="body-xs" color="muted" className="truncate">
                                                                {persona.role}
                                                            </Typography>
                                                        ),
                                                    ]}
                                                />
                                            ),
                                        ]}
                                    />
                                ),
                                ...(ttsSupported
                                    ? [() => (
                                        <button
                                            type="button"
                                            aria-label={ttsEnabled ? muteLabel : unmuteLabel}
                                            aria-pressed={ttsEnabled}
                                            onClick={onToggleTts}
                                            className={cn(
                                                "flex size-8 shrink-0 cursor-pointer items-center justify-center rounded-full transition-colors",
                                                ttsEnabled ? "text-accent-soft-foreground hover:bg-accent-soft" : "text-muted hover:bg-default hover:text-foreground",
                                            )}
                                        >
                                            {ttsEnabled ? (
                                                <SpeakerHighIcon className="size-5" aria-hidden focusable="false" />
                                            ) : (
                                                <SpeakerSlashIcon className="size-5" aria-hidden focusable="false" />
                                            )}
                                        </button>
                                    )]
                                    : []),
                            ]}
                        />
                        {children ? (
                            <div className="mt-3 border-t border-default pt-3">{children}</div>
                        ) : null}
                    </>
                )}
            />
        </div>
    )
}

"use client"

import React, { useCallback, useEffect, useMemo, useRef } from "react"
import {
    addEdge,
    Background,
    BackgroundVariant,
    type Connection,
    Controls,
    type Edge,
    ReactFlow,
    ReactFlowProvider,
    useEdgesState,
    useNodesState,
} from "@xyflow/react"
import { Button, cn } from "@heroui/react"
import { PlusIcon } from "@phosphor-icons/react"
import { useTranslations } from "next-intl"
import { Box } from "@/components/frames/Box"
import { StackH } from "@/components/frames/Stack"
import { BoxNode, MOCK_INTERVIEW_BOX_NODE_TYPE, type MockInterviewBoxNode } from "./BoxNode"
import type { WithClassNames } from "@/modules/types/base/class-name"

/** A single box on the diagram, simplified to the fields a parent actually needs. */
export interface MockInterviewDiagramNodeSnapshot {
    /** Box id. */
    id: string
    /** Box's current label text. */
    label: string
}

/** A single arrow on the diagram, simplified to the fields a parent actually needs. */
export interface MockInterviewDiagramEdgeSnapshot {
    /** Id of the box the arrow starts from. */
    source: string
    /** Id of the box the arrow points to. */
    target: string
}

/** Props for the {@link MockInterviewDiagram} block. */
export interface MockInterviewDiagramProps extends WithClassNames<undefined> {
    /**
     * Fired whenever the boxes or arrows change (add/move/rename/connect/delete),
     * with a plain-object snapshot of the current diagram — not the internal
     * `@xyflow/react` node/edge objects — so a parent can grab the latest state
     * without importing xyflow types.
     */
    onChange?: (
        nodes: Array<MockInterviewDiagramNodeSnapshot>,
        edges: Array<MockInterviewDiagramEdgeSnapshot>,
    ) => void
}

/** Node type map registered on the canvas — a single rectangular labeled box. */
const NODE_TYPES = { [MOCK_INTERVIEW_BOX_NODE_TYPE]: BoxNode }

/** Starting box so the canvas never opens fully empty. */
const INITIAL_NODES: Array<MockInterviewBoxNode> = [
    {
        id: "box-1",
        type: MOCK_INTERVIEW_BOX_NODE_TYPE,
        position: { x: 0, y: 0 },
        data: { label: "New box" },
    },
]

const INITIAL_EDGES: Array<Edge> = []

/** Horizontal/vertical offset applied to each newly added box so they don't stack exactly. */
const NEW_BOX_OFFSET = 40

let nextBoxId = 2

/**
 * The interactive canvas rendered inside {@link MockInterviewDiagram} — split out
 * so it can freely use `@xyflow/react` hooks (`useNodesState`, `useEdgesState`)
 * under a `ReactFlowProvider`.
 */
const MockInterviewDiagramCanvas = ({ className, onChange }: MockInterviewDiagramProps) => {
    const t = useTranslations()
    const [nodes, setNodes, onNodesChange] = useNodesState<MockInterviewBoxNode>(INITIAL_NODES)
    const [edges, setEdges, onEdgesChange] = useEdgesState<Edge>(INITIAL_EDGES)
    /** Position of the most recently added box, so the next one offsets from it (not the origin). */
    const lastAddedPositionRef = useRef(INITIAL_NODES[0]?.position ?? { x: 0, y: 0 })

    const onConnect = useCallback(
        (connection: Connection) => setEdges((current) => addEdge(connection, current)),
        [setEdges],
    )

    const addBox = useCallback(() => {
        const position = {
            x: lastAddedPositionRef.current.x + NEW_BOX_OFFSET,
            y: lastAddedPositionRef.current.y + NEW_BOX_OFFSET,
        }
        lastAddedPositionRef.current = position

        const newNode: MockInterviewBoxNode = {
            id: `box-${nextBoxId++}`,
            type: MOCK_INTERVIEW_BOX_NODE_TYPE,
            position,
            data: { label: t("mockInterview.diagram.newBoxLabel") },
        }
        setNodes((current) => [...current, newNode])
    }, [setNodes, t])

    // notify the parent with a plain-object snapshot whenever boxes or arrows change
    useEffect(() => {
        onChange?.(
            nodes.map((node) => ({ id: node.id, label: node.data.label })),
            edges.map((edge) => ({ source: edge.source, target: edge.target })),
        )
    }, [nodes, edges, onChange])

    const nodeTypes = useMemo(() => NODE_TYPES, [])

    return (
        <div className={cn("relative flex h-full w-full flex-col overflow-hidden rounded-xl", className)}>
            <Box principle="control-pad" className="border-b border-divider bg-surface px-3 py-2"
                explain="Control hit-area inset — not row-pad, because this pads a single interactive control rather than a full content row.">
                <StackH
                    gap={3}
                    principle="flex-action"
                    explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                    justify="between"
                    classNames={["w-full"]}
                    items={[
                        () => (
                            <span className="text-sm font-medium text-foreground">{t("mockInterview.diagram.title")}</span>
                        ),
                        () => (
                            <Button onPress={addBox} size="sm" variant="secondary">
                                <PlusIcon aria-hidden className="size-4" focusable="false" />
                                {t("mockInterview.diagram.addBox")}
                            </Button>
                        ),
                    ]}
                />
            </Box>
            <div className="relative min-h-0 flex-1">
                <ReactFlow
                    aria-label={t("mockInterview.diagram.canvasAria")}
                    className="text-foreground"
                    deleteKeyCode={["Backspace", "Delete"]}
                    edges={edges}
                    fitView
                    fitViewOptions={{ padding: 0.3 }}
                    maxZoom={2}
                    minZoom={0.3}
                    nodeTypes={nodeTypes}
                    nodes={nodes}
                    onConnect={onConnect}
                    onEdgesChange={onEdgesChange}
                    onNodesChange={onNodesChange}
                    proOptions={{ hideAttribution: true }}
                >
                    <Background gap={16} variant={BackgroundVariant.Dots} />
                    <Controls showFitView showInteractive={false} showZoom />
                </ReactFlow>
            </div>
        </div>
    )
}

/**
 * A minimal, self-contained editable box-and-arrow canvas for a mock-interview
 * candidate to sketch a system on. Backed by `@xyflow/react`: add a box from the
 * toolbar, drag it anywhere, double-click a box to rename its label inline, drag
 * from one box's edge to another to draw an arrow between them, select a box or
 * arrow and press `Backspace`/`Delete` to remove it, and pan/zoom the canvas
 * freely. Deliberately minimal — a single box shape, no auto-layout, no
 * grouping/subflows, no persistence, no undo/redo, no export.
 *
 * Wraps the canvas in a `ReactFlowProvider` so its custom node (which reads
 * `useReactFlow()` to commit inline-rename edits) always has store context, even
 * if this block is ever composed with other `@xyflow/react` trees on the page.
 *
 * @param props - {@link MockInterviewDiagramProps}
 */
export const MockInterviewDiagram = (props: MockInterviewDiagramProps) => {
    return (
        <ReactFlowProvider>
            <MockInterviewDiagramCanvas {...props} />
        </ReactFlowProvider>
    )
}

"use client"

import React from "react"
import { Chip, Typography } from "@heroui/react"
