import type { MockInterviewAttemptItem } from "@/modules/api/graphql/queries/types/my-mock-interview-attempts"

/** Props for {@link MockInterviewHistory}. */
export interface MockInterviewHistoryProps {
    /** Course whose mock-interview history to list. */
    courseId: string
    /** Course display id, for the scorecard result deep link. */
    courseDisplayId: string
    /** Jumps the setup tab strip back to "Start" (empty-state action). */
    onStartInterview?: () => void
}

/** History items fetched per "load more" page. */
const PAGE_SIZE = 10

/** The mode filter's fixed option order — "all" first, then the 2 top-level modes. */
type HistoryModeFilter = "all" | "qna" | "design"

/** Verdict → chip color (pass / borderline / fail) — mirrors {@link MockInterviewScorecard}'s convention. */
const verdictColorOf = (verdict: string): "success" | "warning" | "danger" =>
    verdict === "pass" ? "success" : verdict === "borderline" ? "warning" : "danger"

/**
 * The viewer's past mock-interview sessions for this course, newest first — the
 * setup screen's "History" tab. Mirrors the WORKING Flashcard history exactly
 * (teacher, 2026-07-17): fetch ALL modes then filter CLIENT-side (mode facet behind a
 * funnel + search by prompt title), accumulate pages with a `previousCourseIdRef`
 * guard (only a real course change resets — NOT a mere remount), group runs by
 * TIME BUCKET (today / 7 days / 30 days / older), and a "load more" button.
 * Each row opens the read-only scorecard. Server-side `mode` paging was dropped —
 * it desynced `totalCount` from a cleared `items` (count said 12 while the list
 * read empty).
 * @param props - {@link MockInterviewHistoryProps}
 */
export const MockInterviewHistory = ({ courseId, courseDisplayId, onStartInterview}: MockInterviewHistoryProps) => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()

    const [offset, setOffset] = useState(0)
    const [items, setItems] = useState<Array<MockInterviewAttemptItem>>([])
    const [totalCount, setTotalCount] = useState(0)
    const [modeFilter, setModeFilter] = useState<HistoryModeFilter>("all")
    const [search, setSearch] = useState("")
    const [filterOpen, setFilterOpen] = useState(false)

    // fetch ALL modes (no server-side mode filter) — the mode facet narrows the
    // loaded rows client-side, exactly like Flashcard history.
    const attemptsSwr = useQueryMyMockInterviewAttemptsSwr(courseId, PAGE_SIZE, offset)

    // accumulate pages as `offset` advances ("load more").
    useEffect(() => {
        const data = attemptsSwr.data
        if (!data) {
            return
        }
        setItems((previous) => (offset === 0 ? data.items : [...previous, ...data.items]))
        setTotalCount(data.totalCount)
    }, [attemptsSwr.data, offset])

    // course changed → start the accumulator over. Guarded against firing on mere
    // MOUNT (the setup tab remounts this component; an unguarded reset would wipe
    // the `items` the data-effect just set from SWR's warm cache — see
    // FlashcardReviewHistory for the same fix).
    const previousCourseIdRef = useRef(courseId)
    useEffect(() => {
        if (previousCourseIdRef.current === courseId) {
            return
        }
        previousCourseIdRef.current = courseId
        setOffset(0)
        setItems([])
    }, [courseId])

    const formatDate = (iso: string) =>
        new Intl.DateTimeFormat(locale, { dateStyle: "medium" }).format(new Date(iso))

    // only offer a mode the loaded history actually contains — no dead facet.
    const presentModes = useMemo(
        () => Array.from(new Set(items.map((item) => item.mode))),
        [items],
    )
    const filteredItems = useMemo(() => {
        const needle = search.trim().toLowerCase()
        return items.filter((item) =>
            (modeFilter === "all" || item.mode === modeFilter)
            && (!needle || item.promptTitle.toLowerCase().includes(needle)),
        )
    }, [items, modeFilter, search])

    // group filtered runs by time window (teacher, 2026-07-17 "render history day by day")
    const timeBuckets = useMemo(
        () => groupByTimeBucket(filteredItems, (item) => item.createdAt),
        [filteredItems],
    )

    const hasFacets = presentModes.length > 1
    const activeFacetCount = modeFilter !== "all" ? 1 : 0
    const shownCount = search.trim() || activeFacetCount > 0 ? filteredItems.length : totalCount
    const hasMore = items.length < totalCount

    /** One attempt row → opens the read-only scorecard result. Primary line is the
     *  learner's own session name (or its time-based fallback, see
     *  `sessionDisplayName`); the drawn prompt + date move to the subtitle so
     *  neither is lost. */
    const attemptItem = (attempt: MockInterviewAttemptItem): SurfaceCardListItem => ({
        key: attempt.id,
        title: sessionDisplayName(attempt.name, attempt.createdAt, t, locale),
        subtitle: `${attempt.promptTitle} · ${formatDate(attempt.createdAt)}`,
        meta: () => (
            <Chip size="sm" variant="soft" color={verdictColorOf(attempt.verdict)}>
                <Chip.Label>{attempt.overallScore}</Chip.Label>
            </Chip>
        ),
        trailing: () => <CaretRightIcon weight="bold" className="size-4 text-muted" aria-hidden focusable="false" />,
        onPress: () => router.push(
            pathConfig()
                .locale(locale)
                .course(courseDisplayId)
                .learn()
                .mockInterview()
                .interview(attempt.sessionId)
                .result()
                .build(),
        ),
    })

    const skeletonItems: Array<SurfaceCardListItem> = Array.from({ length: 4 }, (_unused, index) => ({
        key: `skeleton-${index}`,
        content: () => (
            <StackH
                gap={4}
                principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                classNames={["w-full"]}
                items={[
                    () => (
                        <StackV
                            gap={2}
                            principle="title-subtitle"
                            explain="Title over supporting line — not label-field, because neither line is a form control label."
                            classNames={["min-w-0", "flex-1"]}
                            items={[
                                () => <Skeleton.Typography type="body-sm" width="1/2" />,
                                () => <Skeleton.Typography type="body-xs" width="1/3" />,
                            ]}
                        />
                    ),
                    () => <Skeleton className="h-6 w-10 shrink-0 rounded-full" />,
                    () => <Skeleton className="size-4 shrink-0 rounded" />,
                ]}
            />
        ),
    }))

    return (
        <AsyncContent
            isLoading={attemptsSwr.isLoading && items.length === 0}
            skeleton={(
                // MIRROR the loaded tree: a funnel toolbar (search + funnel button + count)
                // above a SurfaceCardList of attempt rows (name/subtitle + verdict score
                // chip + caret).
                <StackV
                    gap={4}
                    items={[
                        () => (
                            <StackH
                                gap={4}
                                principle="content-row"
                                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                justify="between"
                                classNames={["w-full"]}
                                items={[
                                    () => (
                                        <StackH
                                            gap={4}
                                            principle="content-row"
                                            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                            classNames={["min-w-0", "flex-1"]}
                                            items={[
                                                () => <Skeleton className="h-9 min-w-0 flex-1 rounded-medium" />,
                                                () => <Skeleton className="size-9 shrink-0 rounded-medium" />,
                                            ]}
                                        />
                                    ),
                                    () => <Skeleton className="h-[14px] w-16 shrink-0 rounded" />,
                                ]}
                            />
                        ),
                        () => (
                            <SurfaceCardList items={skeletonItems} />
                        ),
                    ]}
                />
            )}
            error={items.length === 0 ? attemptsSwr.error : undefined}
            errorContent={{
                title: t("mockInterview.historyError"),
                onRetry: () => void attemptsSwr.mutate(),
                retryLabel: t("mockInterview.promptsRetry"),
            }}
        >
            {items.length === 0 ? (
                // no attempts at all → a single bounded empty card (matches the
                // populated SurfaceCardList shape; components/card.md §2).
                <Card>
                    <CardContent>
                        <EmptyState
                            title={t("mockInterview.historyEmpty")}
                            action={onStartInterview ? () => (
                                <Button size="sm" variant="secondary" onPress={onStartInterview}>
                                    {t("mockInterview.begin")}
                                </Button>
                            ) : undefined}
                        />
                    </CardContent>
                </Card>
            ) : (
                <div>
                    <StackV
                        gap={4}
                        items={[
                            () => (
                                <StackH
                                    gap={4}
                                    principle="content-row"
                                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                    justify="between"
                                    classNames={["w-full"]}
                                    items={[
                                        () => (
                                            <StackH
                                                gap={4}
                                                principle="content-row"
                                                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                classNames={["min-w-0", "flex-1"]}
                                                items={[
                                                    () => (
                                                        <SearchInput
                                                            className="min-w-0 flex-1"
                                                            value={search}
                                                            onValueChange={setSearch}
                                                            placeholder={t("mockInterview.historySearchPlaceholder")}
                                                        />
                                                    ),
                                                    ...(hasFacets
                                                        ? [() => (
                                                            <Popover isOpen={filterOpen} onOpenChange={setFilterOpen}>
                                                                <Button
                                                                    isIconOnly
                                                                    variant="ghost"
                                                                    aria-label={t("mockInterview.historyFilterButton")}
                                                                    className="shrink-0"
                                                                >
                                                                    {activeFacetCount > 0 ? (
                                                                        <Badge.Anchor>
                                                                            <FunnelIcon className="size-5" />
                                                                            <Badge size="sm" color="accent" placement="top-left">{activeFacetCount}</Badge>
                                                                        </Badge.Anchor>
                                                                    ) : (
                                                                        <FunnelIcon className="size-5" />
                                                                    )}
                                                                </Button>
                                                                <Popover.Content className="w-72">
                                                                    <Box principle="cell-pad" className="p-3"
                                                                        explain="Tight cell inset — not card-padding, because this sits inside a dense table or list cell rather than a card body.">
                                                                        <StackV
                                                                            gap={4}
                                                                            items={[
                                                                                () => (
                                                                                    <StackV
                                                                                        gap={4}
                                                                                        principle="label-field"
                                                                                        explain="Form label above its field — not title-subtitle, because the upper line labels an input rather than a heading pair."
                                                                                        items={[
                                                                                            () => (
                                                                                                <Typography type="body-xs" color="muted">{t("mockInterview.historyFilterHeading")}</Typography>
                                                                                            ),
                                                                                            () => (
                                                                                                <FlexWrapButtonRadio<HistoryModeFilter>
                                                                                                    ariaLabel={t("mockInterview.historyFilterHeading")}
                                                                                                    value={modeFilter}
                                                                                                    onChange={setModeFilter}
                                                                                                    items={[
                                                                                                        { value: "all", content: t("mockInterview.historyFilterAll") },
                                                                                                        { value: "qna", content: t("mockInterview.historyFilterQna") },
                                                                                                        { value: "design", content: t("mockInterview.historyFilterDesign") },
                                                                                                    ]}
                                                                                                />
                                                                                            ),
                                                                                        ]}
                                                                                    />
                                                                                ),
                                                                                ...(activeFacetCount > 0
                                                                                    ? [() => (
                                                                                        <Button variant="danger-soft" size="sm" className="self-start" onPress={() => setModeFilter("all")}>
                                                                                            {t("mockInterview.historyClearFilters")}
                                                                                        </Button>
                                                                                    )]
                                                                                    : []),
                                                                            ]}
                                                                        />
                                                                    </Box>
                                                                </Popover.Content>
                                                            </Popover>
                                                        )]
                                                        : []),
                                                ]}
                                            />
                                        ),
                                        () => (
                                            <Typography type="body-sm" color="muted" className="shrink-0">
                                                {t("mockInterview.historyCount", { count: shownCount })}
                                            </Typography>
                                        ),
                                    ]}
                                />
                            ),
                            () => (
                                filteredItems.length === 0 ? (
                                    <Card>
                                        <CardContent>
                                            <Box principle="page-pad" className="p-6"
                                                explain="Page chrome inset — not card-padding, because this pads the whole page rather than a nested card surface.">
                                                <Typography type="body-sm" color="muted" align="center">
                                                    {t("mockInterview.historyEmptyFiltered")}
                                                </Typography>
                                            </Box>
                                        </CardContent>
                                    </Card>
                                ) : (
                                    <StackV
                                        gap={4}
                                        items={timeBuckets.map((bucket) => () => (
                                            <SurfaceCardList
                                                key={bucket.key}
                                                subtleLabel
                                                label={t(`flashcard.timeBucket.${bucket.key}`)}
                                                labelEnd={t("flashcard.runCount", { count: bucket.items.length })}
                                                items={bucket.items.map((attempt) => attemptItem(attempt))}
                                            />
                                        ))}
                                    />
                                )
                            ),
                            ...(hasMore
                                ? [() => (
                                    <Button
                                        variant="secondary"
                                        size="sm"
                                        className="self-center"
                                        isDisabled={attemptsSwr.isLoading}
                                        onPress={() => setOffset((previous) => previous + PAGE_SIZE)}
                                    >
                                        {t("mockInterview.historyLoadMore")}
                                    </Button>
                                )]
                                : []),
                        ]}
                    />
                </div>
            )}
        </AsyncContent>
    )
}

"use client"

import React from "react"
import { useLocale, useTranslations } from "next-intl"
import { useRouter } from "next/navigation"
import { AsyncContentEmpty, AsyncContentError } from "@/components/composites/async/AsyncContent"
import { BackLink } from "@/components/blocks/navigation/BackLink"
import { PageHeader } from "@/components/blocks/layout/PageHeader"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { Button } from "@/components/atoms/buttons/Button"
import { Container } from "@/components/frames/Container"
import { StackV } from "@/components/frames/Stack"
import { pathConfig } from "@/resources/path"
import { useQueryMyMockInterviewAttemptBySessionSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyMockInterviewAttemptBySessionSwr"
import { mapMockInterviewAttemptToGradeResult } from "../mapAttemptToGradeResult"
import { MockInterviewScorecard } from "../MockInterviewScorecard"

/** Props for {@link MockInterviewResult}. */
export interface MockInterviewResultProps {
    /** The graded session to show. */
    sessionId: string
    /** Owning course id (uuid) — enrollment-guard header + track-snapshot scope. */
    courseId: string
    /** Owning course slug — needed to build deep links (study-weak-area CTA, retry). */
    courseDisplayId: string
}

/**
 * The URL-addressable RESULT surface for a GRADED mock-interview run —
 * `mock-interview/interview/[sessionId]/result`. Fetches the attempt fresh by
 * session id ({@link useQueryMyMockInterviewAttemptBySessionSwr}) and maps it
 * through {@link mapMockInterviewAttemptToGradeResult} into the same
 * {@link import("../types").MockInterviewGradeResult} shape the live grading
 * mutation returns, so {@link MockInterviewScorecard} renders identically
 * whether reached via a fresh finish (`MockInterviewSession` redirects here
 * right after grading) or a direct/resumed URL visit — "is this session done"
 * is answered by being on THIS route, never re-derived from `?phase=` client
 * state (2026-07-13, mirrors `flashcards().quiz(sessionId).result()`'s own
 * 2026-07-12 fix for the same class of F5-shows-stale-state bug). No `onRetry`
 * — this is a read-only revisit; "Interview again" goes back to setup instead of
 * silently redrawing a session out from under a URL someone might have shared.
 *
 * The reading measure is stated ONCE on `Container`; it used to be repeated as the
 * same `mx-auto w-full max-w-3xl px-4` string on three separate branches.
 *
 * @param props - {@link MockInterviewResultProps}
 */
export const MockInterviewResult = ({
    sessionId,
    courseId,
    courseDisplayId,
}: MockInterviewResultProps) => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()

    const attemptSwr = useQueryMyMockInterviewAttemptBySessionSwr(sessionId, courseId)
    const attempt = attemptSwr.data
    const isSkeleton = attemptSwr.isLoading && !attempt

    const goToMockInterviewHome = () => {
        router.push(pathConfig().locale(locale).course(courseDisplayId).learn().mockInterview().build())
    }

    // error beats a stale loading flag; the pending-scorecard message is the settled
    // "graded run has no attempt row" case (BLOCK-8 order).
    const scorecard = () => {
        if (attemptSwr.error && !attempt) {
            return (
                <AsyncContentError
                    title={t("mockInterview.scorecardPending")}
                    onRetry={() => { void attemptSwr.mutate() }}
                    retryLabel={t("mockInterview.backToSetup")}
                />
            )
        }
        if (isSkeleton) {
            // each region of the real scorecard is a bordered card, so the resting
            // state is card-shaped too — verdict, track snapshot, phase breakdown.
            return (
                <StackV
                    gap={6}
                    items={[
                        () => <Skeleton.Card lines={2} />,
                        () => <Skeleton.Card lines={3} />,
                        () => <Skeleton.Card lines={3} />,
                    ]}
                />
            )
        }
        if (!attempt) {
            return (
                <AsyncContentEmpty
                    title={t("mockInterview.scorecardPending")}
                    action={() => (
                        <Button
                            label={t("mockInterview.backToSetup")}
                            size="sm"
                            variant="primary"
                            onPress={goToMockInterviewHome}
                        />
                    )}
                />
            )
        }
        return (
            <StackV
                gap={6}
                items={[
                    () => (
                        <MockInterviewScorecard
                            grade={mapMockInterviewAttemptToGradeResult(attempt)}
                            courseId={courseId}
                            courseDisplayId={courseDisplayId}
                            promptTitle={attempt.promptTitle}
                            createdAt={attempt.createdAt}
                        />
                    ),
                    () => (
                        <Button
                            label={t("mockInterview.backToSetup")}
                            variant="tertiary"
                            onPress={goToMockInterviewHome}
                            classNames={["self-start"]}
                        />
                    ),
                ]}
            />
        )
    }

    return (
        <Container
            identity={{ tier: "block", component: "MockInterviewResult" }}
            size="md"
            padding={5}
            body={() => (
                <StackV
                    gap={6}
                    items={[
                        () => (
                            <PageHeader
                                breadcrumb={<BackLink label={t("mockInterview.title")} onPress={goToMockInterviewHome} />}
                                title={t("mockInterview.debriefTitle")}
                            />
                        ),
                        scorecard,
                    ]}
                />
            )}
        />
    )
}

"use client"

import React, { useMemo } from "react"
import {
    Accordion,
    Alert,
    Button,
    Link,
    Typography,
    cn,
} from "@heroui/react"
import {
    ArrowRightIcon,
    ChatCircleIcon,
    CheckCircleIcon,
    WarningCircleIcon,
    XCircleIcon,
} from "@phosphor-icons/react"
import { useLocale, useTranslations } from "next-intl"
import { useRouter } from "next/navigation"
import { CheckListCard, CheckListItem } from "@/components/blocks/cards/CheckListCard"
import { LabeledCard } from "@/components/blocks/cards/LabeledCard"
import { RelatedContentList } from "@/components/blocks/learn/RelatedContentList"
import { SurfaceCardList, type SurfaceCardListItem } from "@/components/composites/cards/SurfaceCard"
import { ProgressMeter } from "@/components/composites/stats/ProgressMeter"
import { MarkdownContent } from "@/components/blocks/rendering/MarkdownContent"
import { StackH, StackV } from "@/components/frames/Stack"
import { FillAvailable } from "@/components/frames/FillAvailable"
import { Cluster } from "@/components/frames/Cluster"
import { useQueryMatchedContentSwr } from "@/hooks/swr/api/graphql/queries/useQueryMatchedContentSwr"
import { pathConfig } from "@/resources/path"
import { MockInterviewTrackSnapshot } from "../MockInterviewTrackSnapshot"
import type { MockInterviewGradeResult, MockInterviewPhaseKey, MockInterviewQuestionReview } from "../types"

/** Props for {@link MockInterviewScorecard}. */
export interface MockInterviewScorecardProps {
    /** The graded result to render (current session, or a past attempt re-opened from history). */
    grade: MockInterviewGradeResult
    /** Course the session belongs to — needed for the track snapshot (B3). */
    courseId: string
    /** Course display id, for building the "study this" deep link (B6) via `pathConfig().course(displayId)`. */
    courseDisplayId: string
    /** System this session worked through, shown as a header line when known. */
    promptTitle?: string
    /** ISO timestamp of when this attempt was graded — shown for history detail, omitted for a live session. */
    createdAt?: string | null
    /** Called when the learner picks "Interview again" (B7, now a tertiary action). Omit to hide the action (e.g. read-only history detail). */
    onRetry?: () => void
}

/** The 3 named attributes the grader always scores, in a fixed display order. */
const ATTRIBUTE_ORDER: ReadonlyArray<string> = [
    "communication",
    "structuredThinking",
    "tradeoffAwareness",
]

/** A phase below this fraction of its max is called out as "weak" (B4/B6) — mirrors the ~60% pass-bar convention used elsewhere in grading result pages. */
const WEAK_PHASE_THRESHOLD = 0.6

/** Verdict → semantic tone (pass / borderline / fail) — drives the verdict Alert status. */
const verdictStatusOf = (verdict: MockInterviewGradeResult["verdict"]): "success" | "warning" | "danger" =>
    verdict === "pass" ? "success" : verdict === "borderline" ? "warning" : "danger"

/** Verdict → Phosphor icon for the Alert indicator. */
const VERDICT_ICON = {
    pass: CheckCircleIcon,
    borderline: WarningCircleIcon,
    fail: XCircleIcon,
} as const

/**
 * Verdict status → soft tint class (literal, so Tailwind emits it). The verdict
 * Alert uses the tinted "in-surface" look (`bg-<status>/10` + `shadow-none`), not
 * the default `bg-surface` + shadow — the scorecard is a tinted result banner and
 * often renders inside the history drawer surface. Mirrors {@link Callout}.
 */
const VERDICT_TINT: Record<"success" | "warning" | "danger", string> = {
    success: "bg-success-soft",
    warning: "bg-warning-soft",
    danger: "bg-danger-soft",
}

/**
 * Score bar color BY VALUE (not always accent): a low score must read as low.
 * &lt;50% of max = danger, &lt;75% = warning, else success.
 */
const scoreColorOf = (score: number, max: number): "success" | "warning" | "danger" => {
    const ratio = max > 0 ? score / max : 0
    return ratio < 0.5 ? "danger" : ratio < 0.75 ? "warning" : "success"
}

/** The 5 canonical design-kind phase keys — used to tell a `kind="design"` phase from a Q&A-kind server-labeled question ("Question 1" …). */
const DESIGN_PHASE_KEYS: ReadonlyArray<MockInterviewPhaseKey> = [
    "requirements",
    "estimation",
    "highLevel",
    "deepDive",
    "tradeoffs",
]

/**
 * Renders a `phaseScores[].phase` value for display. `kind="design"` sends one
 * of the 5 canonical phase keys (i18n-resolved); Q&A kinds instead send a
 * ready-to-render label like `"Question 1"` straight from the server — rendered
 * as-is, no i18n lookup (the scorecard never hardcodes 5 phase labels).
 */
const phaseDisplayLabel = (phase: string, t: ReturnType<typeof useTranslations>): string =>
    (DESIGN_PHASE_KEYS as ReadonlyArray<string>).includes(phase)
        ? t(`mockInterview.phase.${phase}`)
        : phase

/** Score value → semantic text color (mirrors {@link scoreColorOf}) for the per-question score chip. */
const SCORE_TEXT_COLOR: Record<"success" | "warning" | "danger", string> = {
    success: "text-success-soft-foreground",
    warning: "text-warning-soft-foreground",
    danger: "text-danger-soft-foreground",
}

/** The Q&A cognitive frames that carry a localized `mockInterview.kind.*` label — anything else renders raw. */
const QNA_KINDS: ReadonlyArray<string> = ["theory", "reasoning", "scenario"]

/** Props for {@link MockInterviewQuestionReviewCard}. */
interface MockInterviewQuestionReviewCardProps {
    /** One per-question review entry from the scorecard payload. */
    review: MockInterviewQuestionReview
    /** Course display id, for building the "view in lesson" deep link. */
    courseDisplayId: string
}

/**
 * One per-question model-answer review card (the anti-ChatGPT breakdown): the
 * question, the candidate's own answer (muted), the seed flashcard's model answer,
 * a one-line "what was missing" note, a value-colored score chip, and a deep link
 * into the matched lesson when one was confidently matched. Self-contained so each
 * card resolves its OWN `matchedContentId` (one SWR key per question) — mirrors the
 * scorecard's single-match citation mechanism, just per question instead of
 * per session.
 *
 * @param props - {@link MockInterviewQuestionReviewCardProps}
 */
const MockInterviewQuestionReviewCard = ({
    review,
    courseDisplayId,
}: MockInterviewQuestionReviewCardProps) => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()

    // resolve this question's matched lesson (title + owning module id) — the deep
    // link needs BOTH segments; falls back to no link when nothing matched or the
    // content is gone (never fabricate a citation).
    const matchedContentSwr = useQueryMatchedContentSwr(review.matchedContentId ?? undefined)
    const matchedModuleId = matchedContentSwr.data?.module?.id

    const lessonHref = (review.matchedContentId && matchedModuleId)
        ? pathConfig().locale(locale).course(courseDisplayId).learn().module(matchedModuleId).content(review.matchedContentId).build()
        : null

    const kindLabel = QNA_KINDS.includes(review.kind) ? t(`mockInterview.kind.${review.kind}`) : review.kind
    const scoreColor = SCORE_TEXT_COLOR[scoreColorOf(review.score, review.max)]

    return (
        <Accordion.Item id={`question-review-${review.questionIndex}`} aria-label={t("mockInterview.questionReview.heading", { index: review.questionIndex + 1, kind: kindLabel })}>
            <Accordion.Heading>
                <Accordion.Trigger className="w-full">
                    <StackH
                        gap={4}
                        principle="content-row"
                        explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                        justify="between"
                        classNames={["w-full"]}
                        items={[
                            () => (
                                <Typography type="body-sm" weight="medium" className="min-w-0">
                                    {t("mockInterview.questionReview.heading", { index: review.questionIndex + 1, kind: kindLabel })}
                                </Typography>
                            ),
                            () => (
                                <StackH
                                    gap={3}
                                    principle="flex-action"
                                    explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                                    classNames={["shrink-0"]}
                                    items={[
                                        () => (
                                            <Typography type="body-sm" weight="medium" className={scoreColor}>
                                                {t("mockInterview.questionReview.scoreOf", { score: review.score, max: review.max })}
                                            </Typography>
                                        ),
                                        () => <Accordion.Indicator />,
                                    ]}
                                />
                            ),
                        ]}
                    />
                </Accordion.Trigger>
            </Accordion.Heading>
            <Accordion.Panel>
                <Accordion.Body>
                    <StackV
                        gap={3}
                        principle="sibling-stack"
                        explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                        items={[
                            () => <MarkdownContent plain markdown={review.question} />,
                            () => (
                                <StackV
                                    gap={2}
                                    principle="title-subtitle"
                                    explain="Title over supporting line — not label-field, because neither line is a form control label."
                                    items={[
                                        () => (
                                            <Typography type="body-xs" color="muted">{t("mockInterview.questionReview.yourAnswer")}</Typography>
                                        ),
                                        () => (
                                            <MarkdownContent plain markdown={review.candidateAnswer} tone="muted" />
                                        ),
                                    ]}
                                />
                            ),
                            ...(review.modelAnswer
                                ? [() => (
                                    <StackV
                                        gap={2}
                                        principle="title-subtitle"
                                        explain="Title over supporting line — not label-field, because neither line is a form control label."
                                        items={[
                                            () => (
                                                <Typography type="body-xs" color="muted">{t("mockInterview.questionReview.modelAnswer")}</Typography>
                                            ),
                                            () => <MarkdownContent plain markdown={review.modelAnswer ?? ""} />,
                                        ]}
                                    />
                                )]
                                : []),
                            () => (
                                <StackH
                                    gap={3}
                                    principle="icon-text"
                                    explain="Icon beside its label — not name-handle, because this pairs a glyph with feedback text rather than a name/handle identity."
                                    items={[
                                        () => (
                                            <WarningCircleIcon className="size-4 shrink-0 text-warning-soft-foreground" aria-hidden focusable="false" />
                                        ),
                                        () => (
                                            <Typography type="body-sm" className="min-w-0 flex-1">
                                                <span className="text-muted">{t("mockInterview.questionReview.feedback")} </span>
                                                {review.feedback}
                                            </Typography>
                                        ),
                                    ]}
                                />
                            ),
                            ...(lessonHref
                                ? [() => (
                                    <Link
                                        onPress={() => router.push(lessonHref)}
                                        className="group inline-flex cursor-pointer items-center text-accent-soft-foreground"
                                    >
                                        <StackH
                                            gap={2}
                                            principle="icon-text"
                                            explain="Icon beside its label — not name-handle, because this pairs a glyph with text rather than a name/handle identity."
                                            items={[
                                                () => <>{t("mockInterview.viewInLesson")}</>,
                                                () => (
                                                    <ArrowRightIcon aria-hidden focusable="false" className="size-4 transition-transform group-hover:translate-x-1" />
                                                ),
                                            ]}
                                        />
                                    </Link>
                                )]
                                : []),
                        ]}
                    />
                </Accordion.Body>
            </Accordion.Panel>
        </Accordion.Item>
    )
}

/**
 * Read-only render of one graded mock-interview session — score, verdict, a
 * course-grounding citation, a "where you stand" track snapshot, per-phase +
 * per-attribute breakdown, strengths, gaps, and the primary "study your weak
 * area" CTA that closes the demand loop back into the course. Shared between
 * the just-finished session's scorecard and the history detail drawer for a
 * past attempt (a single source of render for "what a graded session looks like").
 *
 * @param props - {@link MockInterviewScorecardProps}
 */
export const MockInterviewScorecard = ({
    grade,
    courseId,
    courseDisplayId,
    promptTitle,
    createdAt,
    onRetry}: MockInterviewScorecardProps) => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()

    // known attribute keys render with a localized label; anything unexpected
    // (the grader is prompted to a fixed set, but AI output isn't guaranteed)
    // falls back to the raw key rather than risking a missing-message error
    const attributeLabel = (key: string): string =>
        ATTRIBUTE_ORDER.includes(key) ? t(`mockInterview.attribute.${key}`) : key

    // order attributes by the fixed display order, then append anything unexpected
    const orderedAttributes = [
        ...ATTRIBUTE_ORDER
            .map((key) => grade.attributeScores.find((attribute) => attribute.key === key))
            .filter((attribute) => attribute !== undefined),
        ...grade.attributeScores.filter((attribute) => !ATTRIBUTE_ORDER.includes(attribute.key)),
    ]

    const formattedDate = createdAt
        ? new Intl.DateTimeFormat(locale, { dateStyle: "medium", timeStyle: "short" }).format(new Date(createdAt))
        : null

    // B2/B4/B6 — resolve the FIRST RAG-matched content id into a title + module id (single
    // representative citation; retrieval already ranks matches, no batch content-by-ids
    // query exists to cheaply resolve every match). Empty matchedContentIds → no citation,
    // fall back to a plain deep link (never fabricate a match).
    const firstMatchedContentId = grade.matchedContentIds[0]
    const matchedContentSwr = useQueryMatchedContentSwr(firstMatchedContentId)
    const matchedContent = matchedContentSwr.data

    // B4/B6 — the single weakest phase (lowest earned/max ratio), when it's actually
    // weak (below threshold) — the CTA and phase-bar link both key off this.
    const weakestPhase = useMemo(() => {
        const weak = grade.phaseScores
            .filter((phaseScore) => phaseScore.max > 0 && phaseScore.score / phaseScore.max < WEAK_PHASE_THRESHOLD)
            .sort((left, right) => (left.score / left.max) - (right.score / right.max))
        return weak[0]
    }, [grade.phaseScores])

    // B6 — deep link routes to the matched content when we have BOTH a content id and
    // its owning module id (the route needs both segments); otherwise falls back to the
    // course-contents home ("Course Contents" landing) so the CTA never dead-ends even when
    // nothing matched.
    const studyHref = (firstMatchedContentId && matchedContent?.module?.id)
        ? pathConfig().locale(locale).course(courseDisplayId).learn().module(matchedContent.module.id).content(firstMatchedContentId).build()
        : pathConfig().locale(locale).course(courseDisplayId).learn().content().build()

    const weakPhaseLabel = weakestPhase ? phaseDisplayLabel(weakestPhase.phase, t) : null

    // query auto-built from the gaps + follow-up question — no typing. This is
    // ADDITIVE to the primary CTA above (which already deep-links matchedContentIds[0]):
    // a fresh course-wide RAG search surfaces a small passive list (may include
    // challenges/flashcards/milestones the single-match CTA never considered).
    const relatedContentQuery = [...grade.gaps, grade.followUpQuestion].filter(Boolean).join(" ")

    // design mode scores against the 5 canonical phases; qna scores are per-question
    // ("Question N") — drives whether the breakdown reads "each phase" or "each question".
    const isDesignScore = grade.phaseScores.length > 0
        && grade.phaseScores.every((phaseScore) => (DESIGN_PHASE_KEYS as ReadonlyArray<string>).includes(phaseScore.phase))

    return (
        <div>
            <StackV
                gap={6}
                principle="block-boundary"
                explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                items={[
                    ...((promptTitle || formattedDate)
                        ? [() => (
                            <StackH
                                gap={4}
                                principle="content-row"
                                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                justify="between"
                                classNames={["w-full"]}
                                items={[
                                    ...(promptTitle
                                        ? [() => <Typography type="body" weight="medium">{promptTitle}</Typography>]
                                        : []),
                                    ...(formattedDate
                                        ? [() => <Typography type="body-xs" color="muted">{formattedDate}</Typography>]
                                        : []),
                                ]}
                            />
                        )]
                        : []),
                    () => (
                        <Alert status={verdictStatusOf(grade.verdict)} className={cn("shadow-none", VERDICT_TINT[verdictStatusOf(grade.verdict)])}>
                            <Alert.Indicator>
                                {React.createElement(VERDICT_ICON[grade.verdict], { className: "size-6", "aria-hidden": true })}
                            </Alert.Indicator>
                            <Alert.Content>
                                <Alert.Title>
                                    <span className="text-2xl font-medium">{grade.overallScore}</span>
                                    <span className="text-muted">/100</span>
                                    {" · "}
                                    {t(`mockInterview.verdict.${grade.verdict}`)}
                                </Alert.Title>
                                <Alert.Description>
                                    <span className="block">
                                        {firstMatchedContentId
                                            ? (matchedContent?.title
                                                ? t("mockInterview.moatCalloutTitled", { title: matchedContent.title })
                                                : t("mockInterview.moatCalloutUntitled"))
                                            : t("mockInterview.moatCalloutGeneric")}
                                    </span>
                                    <span className="block text-muted">{t("mockInterview.serverUnverifiedHint")}</span>
                                </Alert.Description>
                            </Alert.Content>
                        </Alert>
                    ),
                    () => <MockInterviewTrackSnapshot courseId={courseId} />,
                    () => (
                        <LabeledCard label={isDesignScore ? t("mockInterview.perPhaseTitle") : t("mockInterview.perQuestionTitle")}>
                            <StackV
                                gap={4}
                                items={grade.phaseScores.map((phaseScore) => () => (
                                    <StackH
                                        gap={4}
                                        principle="content-row"
                                        explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                        classNames={["w-full"]}
                                        items={[
                                            () => (
                                                <Typography type="body-sm" className="w-40 shrink-0">
                                                    {phaseDisplayLabel(phaseScore.phase, t)}
                                                </Typography>
                                            ),
                                            () => (
                                                <FillAvailable
                                                    at="base"
                                                    body={() => (
                                                        <ProgressMeter
                                                            value={phaseScore.score}
                                                            max={phaseScore.max}
                                                            color={scoreColorOf(phaseScore.score, phaseScore.max)}
                                                        />
                                                    )}
                                                />
                                            ),
                                        ]}
                                    />
                                ))}
                            />
                        </LabeledCard>
                    ),

                    ...(grade.questionReviews.length > 0
                        ? [() => (
                            <LabeledCard label={t("mockInterview.questionReview.title")} frameless>
                                <Accordion variant="surface" className="overflow-hidden border border-default" allowsMultipleExpanded>
                                    {grade.questionReviews.map((review) => (
                                        <MockInterviewQuestionReviewCard
                                            key={review.questionIndex}
                                            review={review}
                                            courseDisplayId={courseDisplayId}
                                        />
                                    ))}
                                </Accordion>
                            </LabeledCard>
                        )]
                        : []),
                    ...(orderedAttributes.length > 0
                        ? [() => (
                            <LabeledCard label={t("mockInterview.attributesTitle")}>
                                <StackV
                                    gap={4}
                                    items={orderedAttributes.map((attribute) => () => (
                                        <StackH
                                            gap={4}
                                            principle="content-row"
                                            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                            classNames={["w-full"]}
                                            items={[
                                                () => (
                                                    <Typography type="body-sm" className="w-40 shrink-0">
                                                        {attributeLabel(attribute.key)}
                                                    </Typography>
                                                ),
                                                () => (
                                                    <FillAvailable
                                                        at="base"
                                                        body={() => (
                                                            <ProgressMeter
                                                                value={attribute.score}
                                                                max={100}
                                                                color={scoreColorOf(attribute.score, 100)}
                                                            />
                                                        )}
                                                    />
                                                ),
                                            ]}
                                        />
                                    ))}
                                />
                            </LabeledCard>
                        )]
                        : []),
                    ...(grade.strengths.length > 0
                        ? [() => (
                            <LabeledCard label={t("mockInterview.strengthsTitle")} frameless>
                                <CheckListCard>
                                    {grade.strengths.map((strength, position) => (
                                        <CheckListItem key={position}>
                                            <MarkdownContent plain markdown={strength} />
                                        </CheckListItem>
                                    ))}
                                </CheckListCard>
                            </LabeledCard>
                        )]
                        : []),
                    ...(grade.gaps.length > 0
                        ? [() => {
                            const gapItems: Array<SurfaceCardListItem> = grade.gaps.map((gap, position) => ({
                                key: `gap-${position}`,
                                content: () => (
                                    <StackH
                                        gap={3}
                                        principle="icon-text"
                                        explain="Icon beside its label — not name-handle, because this pairs a glyph with gap markdown rather than a name/handle identity."
                                        items={[
                                            () => (
                                                <WarningCircleIcon className="size-4 shrink-0 text-warning-soft-foreground" aria-hidden focusable="false" />
                                            ),
                                            () => (
                                                <FillAvailable
                                                    at="base"
                                                    explain="Gap prose takes remaining row width beside the warning glyph so long markdown wraps without overflow."
                                                    body={() => (
                                                        <MarkdownContent plain markdown={gap} />
                                                    )}
                                                />
                                            ),
                                        ]}
                                    />
                                ),
                            }))
                            return (
                                <SurfaceCardList
                                    label={t("mockInterview.gapsTitle")}
                                    items={gapItems}
                                />
                            )
                        }]
                        : []),
                    ...(grade.followUpQuestion
                        ? [() => (
                            <LabeledCard label={t("mockInterview.followUpTitle")}>
                                <StackH
                                    gap={3}
                                    principle="icon-text"
                                    explain="Icon beside its label — not name-handle, because this pairs a glyph with follow-up markdown rather than a name/handle identity."
                                    items={[
                                        () => (
                                            <ChatCircleIcon className="size-4 shrink-0 text-accent-soft-foreground" aria-hidden focusable="false" />
                                        ),
                                        () => (
                                            <FillAvailable
                                                at="base"
                                                explain="Follow-up question takes remaining row width beside the chat glyph so italic prose wraps without overflow."
                                                body={() => (
                                                    <MarkdownContent
                                                        plain
                                                        markdown={grade.followUpQuestion ?? ""}
                                                        emphasis="italic"
                                                    />
                                                )}
                                            />
                                        ),
                                    ]}
                                />
                            </LabeledCard>
                        )]
                        : []),
                    () => (
                        <Cluster
                            gap={3}
                            principle="flex-action"
                            explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                            items={[
                                () => (
                                    <Button
                                        variant="primary"
                                        size="lg"
                                        onPress={() => router.push(studyHref)}
                                    >
                                        {weakPhaseLabel
                                            ? t("mockInterview.weakPhaseCta", { phase: weakPhaseLabel })
                                            : t("mockInterview.weakPhaseCtaGeneric")}
                                        <ArrowRightIcon className="size-5" aria-hidden focusable="false" />
                                    </Button>
                                ),
                                () => (
                                    <Button
                                        variant="tertiary"
                                        onPress={() => router.push(
                                            pathConfig().locale(locale).course(courseDisplayId).learn().personalProject().build(),
                                        )}
                                    >
                                        {t("mockInterview.capstoneCta")}
                                    </Button>
                                ),
                                ...(onRetry
                                    ? [() => (
                                        <Button variant="tertiary" onPress={onRetry}>
                                            {t("mockInterview.retry")}
                                        </Button>
                                    )]
                                    : []),
                            ]}
                        />
                    ),
                    () => (
                        <RelatedContentList
                            courseId={courseId}
                            courseDisplayId={courseDisplayId}
                            query={relatedContentQuery}
                            label={t("mockInterview.relatedContentLabel")}
                        />
                    ),
                ]}
            />
        </div>
    )
}

import React from "react"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { SurfaceCard } from "@/components/composites/cards/SurfaceCard"
