/**
 * Loading placeholder for the mock-interview green room's "You're about to be
 * interviewed" card — the only piece of {@link import("../index").MockInterviewPage}
 * visible before `courseId`/`courseDisplayId`/the enrollment check resolve.
 * Mirrors the real card 1:1: persona avatar + name/role, the title + "N questions ·
 * level X · ~Y minutes" meta line, and the primary CTA — so resolving never
 * collapses or jumps the surface.
 */
export const MockInterviewSetupSkeleton = ({ className }: WithClassNames<undefined> = {}) => {
    return (
        <div className={className}>
            <SurfaceCard
                padding={6}
                body={() => (
                    <StackV
                        gap={5}
                        principle="group-boundary"
                        explain="Section group spacing — not sibling-stack, because these blocks are distinct groups rather than same-kind peers."
                        items={[
                            () => (
                                <StackH
                                    gap={3}
                                    principle="identity"
                                    explain="Keeps avatar and identity text as one peer unit so the person label stays beside the face."
                                    items={[
                                        () => <Skeleton.Avatar size="lg" />,
                                        () => (
                                            <StackV
                                                gap={2}
                                                principle="title-subtitle"
                                                explain="Title over supporting line — not label-field, because neither line is a form control label."
                                                classNames={["min-w-0"]}
                                                items={[
                                                    () => <Skeleton.Typography type="body" width="1/3" />,
                                                    () => <Skeleton.Typography type="body-xs" width="1/4" />,
                                                ]}
                                            />
                                        ),
                                    ]}
                                />
                            ),
                            () => (
                                <StackV
                                    gap={2}
                                    principle="title-subtitle"
                                    explain="Title over supporting line — not label-field, because neither line is a form control label."
                                    items={[
                                        () => <Skeleton.Typography type="h4" width="1/2" />,
                                        () => <Skeleton.Typography type="body-sm" width="2/3" />,
                                    ]}
                                />
                            ),
                            () => <Skeleton.Button width="w-48" />,
                        ]}
                    />
                )}
            />
        </div>
    )
}

"use client"

import React from "react"
import { Button, Typography } from "@heroui/react"
import { ArrowRightIcon, ChartLineUpIcon } from "@phosphor-icons/react"
import { useTranslations } from "next-intl"
import { AsyncContent } from "@/components/blocks/async/AsyncContent"
import { EmptyState } from "@/components/composites/feedback/EmptyState"
import { SurfaceCard } from "@/components/composites/cards/SurfaceCard"
import { SurfaceCardHeader } from "@/components/composites/cards/SurfaceCard/surface-card-header"
import { SectionCard } from "@/components/blocks/cards/SectionCard"
import { RelatedContentList } from "@/components/blocks/learn/RelatedContentList"
import { ProgressMeter } from "@/components/composites/stats/ProgressMeter"
import { VerdictHeroCard } from "@/components/blocks/stats/VerdictHeroCard"
import type { VerdictHeroBand } from "@/components/blocks/stats/VerdictHeroCard"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { StackH, StackV } from "@/components/frames/Stack"
import { FillAvailable } from "@/components/frames/FillAvailable"
import { useQueryMyMockInterviewStatsSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyMockInterviewStatsSwr"
import type { MockInterviewStatsBreakdownItem } from "@/modules/api/graphql/queries/types/my-mock-interview-stats"
import { ProgrammingLanguage } from "@/modules/types/enums/programming-language"

/** Props for {@link MockInterviewStats}. */
export interface MockInterviewStatsProps {
    /** Course whose aggregate mock-interview stats to show. */
    courseId: string
    /** Course display id, for the weakest-phase/kind CTA's deep link. */
    courseDisplayId: string
    /** Jumps the setup tab strip back to "Start" (empty-state action, and also the readiness hero's "practice more" CTA when not yet at {@link PASS_BAR}). */
    onStartInterview?: () => void
}

/** Every breakdown axis this surface folds a `MockInterviewStatsBreakdownItem` list by. */
type BreakdownAxis = "phase" | "kind" | "attribute" | "level" | "language"

/** Score bar color BY VALUE (not always accent) — mirrors `MockInterviewScorecard`'s own `scoreColorOf`. Used for the per-row breakdown meters and the trend bars (absolute 0-100 quality reads), NOT the readiness hero (that one is relative to {@link PASS_BAR} — see `readinessBandOf`). */
const scoreColorOf = (score: number, max: number): "success" | "warning" | "danger" => {
    const ratio = max > 0 ? score / max : 0
    return ratio < 0.5 ? "danger" : ratio < 0.75 ? "warning" : "success"
}

/** Every language {@link ProgrammingLanguage} covers — used to tell a real implementation-track language (translated) apart from a raw drawn-language string (fallback-capitalized), mirrors `MockInterviewWorkspace`'s own `KNOWN_PROGRAMMING_LANGS`. */
const KNOWN_PROGRAMMING_LANGS: ReadonlySet<string> = new Set(Object.values(ProgrammingLanguage))

/** No dedicated BE field yet for the interview "pass" line — a local const, same convention `MockInterviewScorecard`'s own `WEAK_PHASE_THRESHOLD` uses for a hardcoded interview-domain constant. */
const PASS_BAR = 70

/** Below this fraction of {@link PASS_BAR} the readiness hero reads as `"danger"` rather than `"warning"` — proportional (not a flat point gap) so the same margin scales with the bar itself. */
const READINESS_WARNING_RATIO = 0.8

/** Readiness band relative to {@link PASS_BAR} (NOT the absolute-quality {@link scoreColorOf} scale — a 64 there is "warning" purely because it's <75/100, whereas here it's "warning" because it's close-but-under the pass line). */
const readinessBandOf = (avgScore: number): VerdictHeroBand =>
    avgScore >= PASS_BAR ? "success" : avgScore >= PASS_BAR * READINESS_WARNING_RATIO ? "warning" : "danger"

/**
 * Mock-interview aggregate stats — the setup screen's "Stats" tab, condensed
 * per `stats-canonical-fold` (1 hero + 1 zone): a readiness hero (vs
 * {@link PASS_BAR}, "~N sessions to go" projected from the recent trend delta) +
 * the per-phase breakdown. Gated behind a minimum-attempts floor
 * (server-enforced via `insufficientData`) so a near-empty history never
 * reads as a broken dashboard of fabricated percentages.
 * @param props - {@link MockInterviewStatsProps}
 */
export const MockInterviewStats = ({ courseId, courseDisplayId, onStartInterview}: MockInterviewStatsProps) => {
    const t = useTranslations()

    const statsSwr = useQueryMyMockInterviewStatsSwr(courseId)
    const stats = statsSwr.data

    const axisLabel = (axis: BreakdownAxis, key: string): string => {
        switch (axis) {
        case "phase":
            return t(`mockInterview.phase.${key}`)
        case "kind":
            return t(`mockInterview.kind.${key}`)
        case "attribute":
            return t(`mockInterview.attribute.${key}`)
        case "level":
            // junior/middle/senior/staff — shared vocabulary, reuses the flashcard
            // module's own level labels rather than duplicating a 4th copy of them.
            return t(`flashcard.level.${key}`)
        case "language":
            // byLanguage keys are drawn from a question's ProgrammingLanguage (the
            // 4 implementation tracks); an unrecognized one still reads as a plain
            // label instead of a raw i18n key, mirrors MockInterviewWorkspace's own
            // displayLangLabel fallback.
            return KNOWN_PROGRAMMING_LANGS.has(key) ? t(`programmingLanguage.${key}`) : key.charAt(0).toUpperCase() + key.slice(1)
        }
    }

    const renderBreakdown = (
        items: ReadonlyArray<MockInterviewStatsBreakdownItem>,
        axis: BreakdownAxis,
        subtitleFor?: (item: MockInterviewStatsBreakdownItem) => React.ReactNode,
    ) => (
        <StackV
            gap={4}
            items={items.map((item) => () => (
                <StackH
                    gap={4}
                    principle="content-row"
                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                    classNames={["w-full"]}
                    items={[
                        () => (
                            <StackV
                                gap={1}
                                principle="name-handle"
                                explain="Display name with handle — not title-subtitle, because the second line is an identity handle rather than a subtitle."
                                classNames={["shrink-0"]}
                                items={[
                                    () => (
                                        <Typography type="body-sm" className="w-40">
                                            {axisLabel(axis, item.key)}
                                        </Typography>
                                    ),
                                    () => (
                                        <Typography type="body-xs" color="muted" className="w-40">
                                            {subtitleFor ? subtitleFor(item) : t("mockInterview.statsWeakRatioCaption", { weak: item.weakCount, total: item.attemptCount })}
                                        </Typography>
                                    ),
                                ]}
                            />
                        ),
                        () => (
                            <FillAvailable
                                at="base"
                                body={() => (
                                    <ProgressMeter
                                        value={Math.round(item.avgScore)}
                                        max={Math.round(item.avgMax) || 100}
                                        color={scoreColorOf(item.avgScore, item.avgMax)}
                                        showValue
                                    />
                                )}
                            />
                        ),
                    ]}
                />
            ))}
        />
    )

    return (
        <AsyncContent
            isLoading={statsSwr.isLoading && !stats}
            skeleton={(
                // MIRROR the loaded tree: ZONE 1 label + readiness verdict hero (value ·
                // verdict · trend sub · meter · CTA), ZONE 2 label + per-phase breakdown of
                // label/caption + ProgressMeter rows.
                <StackV
                    gap={6}
                    principle="block-boundary"
                    explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                    items={[
                        () => (
                            <StackV
                                gap={4}
                                items={[
                                    () => <Skeleton className="h-[14px] w-40 rounded" />,
                                    () => (
                                        <SectionCard>
                                            <StackH
                                                gap={3}
                                                principle="value-row"
                                                explain="Holds a label and its numeric value on one baseline so the count stays readable against the label."
                                                align="baseline"
                                                items={[
                                                    () => <Skeleton className="h-9 w-20 rounded" />,
                                                    () => <Skeleton className="h-[14px] w-8 rounded" />,
                                                ]}
                                            />
                                            <Skeleton.Typography type="body-sm" width="3/4" />
                                            <Skeleton.Typography type="body-xs" width="1/2" />
                                            <Skeleton.ProgressBar />
                                            <Skeleton.Button width="w-44" />
                                        </SectionCard>
                                    ),
                                ]}
                            />
                        ),
                        () => (
                            <StackV
                                gap={4}
                                items={[
                                    () => <Skeleton className="h-[14px] w-32 rounded" />,
                                    () => (
                                        <StackV
                                            gap={4}
                                            items={Array.from({ length: 4 }).map((_unused, index) => () => (
                                                <StackH
                                                    key={index}
                                                    gap={4}
                                                    principle="content-row"
                                                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                    classNames={["w-full"]}
                                                    items={[
                                                        () => (
                                                            <StackV
                                                                gap={2}
                                                                principle="title-subtitle"
                                                                explain="Title over supporting line — not label-field, because neither line is a form control label."
                                                                classNames={["shrink-0"]}
                                                                items={[
                                                                    () => <Skeleton.Typography type="body-sm" width="2/3" />,
                                                                    () => <Skeleton.Typography type="body-xs" width="1/2" />,
                                                                ]}
                                                            />
                                                        ),
                                                        () => <Skeleton.ProgressBar className="flex-1" />,
                                                    ]}
                                                />
                                            ))}
                                        />
                                    ),
                                ]}
                            />
                        ),
                    ]}
                />
            )}
            error={!stats ? statsSwr.error : undefined}
            errorContent={{
                title: t("mockInterview.statsError"),
                onRetry: () => { void statsSwr.mutate() },
                retryLabel: t("mockInterview.promptsRetry"),
            }}
        >
            {!stats || stats.insufficientData ? (
                <EmptyState
                    icon={ChartLineUpIcon}
                    title={t("mockInterview.statsInsufficientTitle")}
                    description={t("mockInterview.statsInsufficientDescription")}
                    action={onStartInterview ? () => (
                        <Button size="sm" variant="secondary" onPress={onStartInterview}>
                            {t("mockInterview.begin")}
                        </Button>
                    ) : undefined}
                />
            ) : (
                <div>
                    <StackV
                        gap={6}
                        principle="block-boundary"
                        explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                        items={[
                            () => (
                                // B37 Decision E: VerdictHeroCard self-frames — StackV
                                // label-field replaces LabeledCard frameless + description slot.
                                <StackV
                                    gap={3}
                                    principle="label-field"
                                    explain="Section label above its control is label-field — not title-subtitle (no paired title/supporting lines), not name-handle, not icon-text; the label names the surface the way a field label names its control."
                                    items={[
                                        () => <SurfaceCardHeader label={t("mockInterview.statsReadinessLabel")} />,
                                        () => {
                                            const avgScore = Math.round(
                                                stats.trend.reduce((sum, point) => sum + point.overallScore, 0) / Math.max(1, stats.trend.length),
                                            )
                                            const recentScores = stats.trend.slice(-3).map((point) => point.overallScore)
                                            const trendDelta = recentScores.length >= 2
                                                ? (recentScores[recentScores.length - 1] - recentScores[0]) / (recentScores.length - 1)
                                                : 0
                                            const sessionsNeeded = Math.max(1, trendDelta > 0 ? Math.ceil((PASS_BAR - avgScore) / trendDelta) : 1)
                                            const band = readinessBandOf(avgScore)
                                            return (
                                                <VerdictHeroCard
                                                    value={avgScore}
                                                    unit="/100"
                                                    band={band}
                                                    verdict={band === "success" ? t("mockInterview.statsVerdictPass") : t("mockInterview.statsReadinessAlmostSentence", { sessionsNeeded })}
                                                    sub={t("mockInterview.statsReadinessTrendCaption", {
                                                        passBar: PASS_BAR,
                                                        count: recentScores.length,
                                                        scores: recentScores.join(" → "),
                                                    })}
                                                    meter={{ value: avgScore, max: 100, target: PASS_BAR }}
                                                    action={band !== "success" && onStartInterview ? () => (
                                                        <Button variant="primary" size="sm" onPress={onStartInterview}>
                                                            {t("mockInterview.statsReadinessPracticeMoreCta", { count: sessionsNeeded })}
                                                            <ArrowRightIcon className="size-4" aria-hidden focusable="false" />
                                                        </Button>
                                                    ) : undefined}
                                                />
                                            )
                                        },
                                        () => (
                                            <Typography type="body-xs" color="muted">
                                                {t("mockInterview.statsModeSplitCaption", {
                                                    qna: stats.modeSplit.qnaCount,
                                                    design: stats.modeSplit.designCount,
                                                })}
                                            </Typography>
                                        ),
                                    ]}
                                />
                            ),
                            ...(stats.byPhase.length > 0
                                ? [() => (
                                    <SurfaceCard
                                        label={t("mockInterview.statsByPhaseTitle")}
                                        body={() => renderBreakdown(stats.byPhase, "phase")}
                                    />
                                )]
                                : []),
                            () => (
                                <RelatedContentList
                                    courseId={courseId}
                                    courseDisplayId={courseDisplayId}
                                    query={[...stats.byPhase]
                                        .sort((a, b) => a.avgScore - b.avgScore)
                                        .slice(0, 3)
                                        .map((item) => axisLabel("phase", item.key))
                                        .join(" ")}
                                    label={t("mockInterview.statsStudyHeading")}
                                />
                            ),
                        ]}
                    />
                </div>
            )}
        </AsyncContent>
    )
}

"use client"

import React from "react"
import { Chip, Typography } from "@heroui/react"
import { useTranslations } from "next-intl"
import { StatPair } from "@/components/composites/stats/StatPair"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { useQueryMyJobReadinessSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyJobReadinessSwr"
import type { UserJobReadinessBand } from "@/modules/api/graphql/queries/types/user-job-readiness"

/** Props for {@link MockInterviewTrackSnapshot}. */
export interface MockInterviewTrackSnapshotProps {
    /** Course whose job-readiness track to show — filters the viewer's own `myJobReadiness.tracks`. */
    courseId: string
}

/** Maps a readiness band to the `Chip` color that reads correctly (mirrors {@link JobReadinessWidget}). */
const bandColorOf = (band: UserJobReadinessBand): "success" | "warning" | "default" =>
    band === "jobReady" ? "success" : band === "building" ? "warning" : "default"

/**
 * "Where you stand" snapshot for ONE course's job-readiness track — the interview
 * pillar's best score, plus the track's overall depth band. Shared between the
 * setup screen (before starting a new run) and the scorecard (right after grading)
 * so both read the exact same number (single source of render).
 *
 * Deliberately does NOT claim a rolling-5-average / delta-to-next-band number: the
 * `myJobReadiness` query only exposes `interviewScore` as a BEST-of score and `band`
 * as the track's blended composite (capstone + interview + cv), not an
 * interview-specific rolling window with a "one more run" delta. Showing a made-up
 * delta would misrepresent the real fairness mechanic (see `WF-09-interview-recent-window`)
 * — this renders only what the query actually returns.
 *
 * Self-hides when the viewer has never attempted this course's track at all (a
 * fresh learner with zero pillars shouldn't see a hollow snapshot before their
 * first attempt) — the setup screen and scorecard both gate rendering by null.
 *
 * @param props - {@link MockInterviewTrackSnapshotProps}
 */
export const MockInterviewTrackSnapshot = ({ courseId}: MockInterviewTrackSnapshotProps) => {
    const t = useTranslations()
    const readinessSwr = useQueryMyJobReadinessSwr()
    const data = readinessSwr.data
    const track = data?.tracks.find((candidate) => candidate.courseId === courseId)

    // 2026-07-12: this only mounts inside an already-rendered setup/scorecard
    // screen, so a bare `return null` while `readinessSwr` is still loading was
    // indistinguishable from "genuinely nothing to show" — it popped in above the
    // persona card / into the alert stack a beat after the screen had settled.
    if (readinessSwr.isLoading && !data) {
        return (
            <div className={"flex flex-wrap items-center gap-3 rounded-xl bg-default/40 p-4"}>
                <Skeleton.Typography type="h4" width="1/4" />
                <Skeleton className="h-6 w-20 rounded-full" />
            </div>
        )
    }

    // no track yet (never enrolled-scored anything) — nothing meaningful to show
    if (!track) {
        return null
    }
    // interview pillar never attempted — the snapshot has nothing interview-specific to say
    if (track.interviewScore === null) {
        return null
    }

    return (
        <div className={"flex flex-wrap items-center gap-3 rounded-xl bg-default/40 p-4"}>
            <StatPair value={String(track.interviewScore)} label={t("mockInterview.trackSnapshotLabel")} />
            <Chip size="md" variant="soft" color={bandColorOf(track.band)}>
                <Chip.Label>{t(`jobReadiness.band.${track.band}`)}</Chip.Label>
            </Chip>
            <Typography type="body-xs" color="muted">
                {t("mockInterview.trackSnapshotHint")}
            </Typography>
        </div>
    )
}

"use client"

import React from "react"
import {
    ListBox,
    Select,
    cn,
} from "@heroui/react"
import CodeMirror from "@uiw/react-codemirror"
import { java } from "@codemirror/lang-java"
import { javascript } from "@codemirror/lang-javascript"
import { StreamLanguage } from "@codemirror/language"
import type { Extension } from "@codemirror/state"
import { csharp } from "@codemirror/legacy-modes/mode/clike"
import { dockerFile } from "@codemirror/legacy-modes/mode/dockerfile"
import { go } from "@codemirror/legacy-modes/mode/go"
import { whiteLight } from "@uiw/codemirror-theme-white"
import { vscodeDark } from "@uiw/codemirror-theme-vscode"
import { useTheme } from "next-themes"
import { useTranslations } from "next-intl"
import { ProgrammingLanguage } from "@/modules/types/enums/programming-language"
import type { WithClassNames } from "@/modules/types/base/class-name"
import { MockInterviewDiagram } from "../MockInterviewDiagram"
import type {
    MockInterviewDiagramEdgeSnapshot,
    MockInterviewDiagramNodeSnapshot,
} from "../MockInterviewDiagram"

/** Every language {@link ProgrammingLanguage} covers — used to tell an implementation-track
 *  language apart from an arbitrary content language (`dockerfile`, `yaml`, …) below. */
const KNOWN_PROGRAMMING_LANGS: ReadonlySet<string> = new Set(Object.values(ProgrammingLanguage))

/**
 * CodeMirror language extension for the workspace's given code — NOT restricted to
 * {@link ProgrammingLanguage} (a debug/review/optimize question can ship ANY content language
 * authored in `.mount`, e.g. `dockerfile`). TypeScript/Java use official `@codemirror/lang-*`
 * packages; Csharp/Go/Dockerfile have no first-party CM6 package, so they fall back to
 * `@codemirror/legacy-modes`' ported CM5 grammars (still solid token-level highlighting).
 * Anything else falls back to NO language extension (plain, still fully editable) rather than
 * silently mislabeling it as TypeScript (2026-07-17 fix — the prior default did exactly that).
 */
const languageExtensionFor = (lang: string): Array<Extension> => {
    switch (lang) {
    case ProgrammingLanguage.Java:
        return [java()]
    case ProgrammingLanguage.Csharp:
        return [StreamLanguage.define(csharp)]
    case ProgrammingLanguage.Go:
        return [StreamLanguage.define(go)]
    case "dockerfile":
        return [StreamLanguage.define(dockerFile)]
    case ProgrammingLanguage.TypeScript:
        return [javascript({ typescript: true })]
    default:
        return []
    }
}

/**
 * Which tool the {@link MockInterviewWorkspace} shows — driven ENTIRELY by the
 * current question, never by a candidate-facing switcher (2026-07-09 feedback:
 * a manual Whiteboard/Code/Notes tab bar read as "pointless" busywork). A
 * debug/review/optimize question (given code) renders straight to `"code"`; a
 * `mode="design"` phase renders straight to `"whiteboard"`.
 */
type MockInterviewTool = "whiteboard" | "code"

/** Controlled code-tab state (language + source), lifted so switching tabs never loses it. */
export interface MockInterviewCodeState {
    /**
     * Language the given code is authored in — a raw content-language string, NOT narrowed to
     * {@link ProgrammingLanguage} (that enum is the 4 CANDIDATE-CHOSEN implementation tracks;
     * a debug/review/optimize question's given code can be any authored language, e.g. `dockerfile`).
     */
    lang: string
    /** Code buffer. */
    code: string
}

/** Props for {@link MockInterviewWorkspace}. */
export interface MockInterviewWorkspaceProps extends WithClassNames<undefined> {
    /** Which tool renders — set by the caller from the current question, not by the candidate. */
    tool: MockInterviewTool
    /** Whiteboard change callback — mirrors {@link MockInterviewDiagram}'s `onChange` (read at grade time). */
    onDiagramChange: (
        nodes: Array<MockInterviewDiagramNodeSnapshot>,
        edges: Array<MockInterviewDiagramEdgeSnapshot>,
    ) => void
    /** Controlled code-tab state. */
    codeState: MockInterviewCodeState
    /** Fired with the next code-tab state. */
    onCodeStateChange: (next: MockInterviewCodeState) => void
    /**
     * Every authored language variant of the CURRENT question's given code —
     * switching the language `Select` looks up the matching variant here and
     * swaps `codeState.code` to it, client-side, no refetch (mirrors
     * `ChallengeView`'s own per-language step content). Empty when the
     * current question has no given code (`tool !== "code"`).
     */
    givenCodeVariants?: Array<{ lang: string, code: string }>
}

/** Default code-tab state — TypeScript, empty buffer. */
export const MOCK_INTERVIEW_CODE_STATE_DEFAULT: MockInterviewCodeState = {
    lang: ProgrammingLanguage.TypeScript,
    code: "",
}

/**
 * The mock interview's right-pane WORKSPACE — renders straight to the ONE tool
 * the current question needs (no candidate-facing switcher): the
 * {@link MockInterviewDiagram} xyflow canvas for a `mode="design"` phase, or a
 * CodeMirror code editor for a debug/review/optimize question's given code.
 *
 * Both stay MOUNTED (toggled with `hidden`, not conditionally rendered) so an
 * in-progress sketch survives a `qna` session moving between a code question
 * and a plain one.
 *
 * @param props - {@link MockInterviewWorkspaceProps}
 */
export const MockInterviewWorkspace = ({
    tool,
    onDiagramChange,
    codeState,
    onCodeStateChange,
    givenCodeVariants = [],
    className,
}: MockInterviewWorkspaceProps) => {
    const t = useTranslations()
    const { theme } = useTheme()

    // display label for a language — translated for the 4 real implementation tracks,
    // capitalized-as-authored for anything else (`dockerfile`, `yaml`, …) so an
    // uncommon content language reads as a normal label instead of a raw i18n key
    // (2026-07-17 fix — see `languageExtensionFor`'s doc for the same root cause).
    const displayLangLabel = (lang: string): string =>
        KNOWN_PROGRAMMING_LANGS.has(lang) ? t(`programmingLanguage.${lang}`) : lang.charAt(0).toUpperCase() + lang.slice(1)

    // only offer languages actually AUTHORED for this question (mirrors
    // ChallengeView only showing tabs for languages that exist).
    const availableLangs = givenCodeVariants.map((variant) => variant.lang)
    const languageItems = availableLangs.map((lang) => ({
        id: lang,
        title: displayLangLabel(lang),
    }))
    const selectedLanguageTitle = languageItems.find((item) => item.id === codeState.lang)?.title

    return (
        <div className={cn("flex h-full flex-col gap-3", className)}>
            <div className={cn("min-h-0 flex-1", tool !== "whiteboard" && "hidden")}>
                <MockInterviewDiagram className="h-full" onChange={onDiagramChange} />
            </div>

            {/* a REAL editor (CodeMirror) — a debug/review/optimize question seeds its given
                code here for the candidate to FIX in place (not a plain textarea): line numbers +
                syntax highlighting = editing, not narrating. Switched from Monaco (2026-07-17,
                instructor: "this code terminal looks kind of ugly" + pointed at react-codemirror's theme gallery) —
                CM6 ships a clean, tunable theme system (no VS-Code-IDE chrome to fight) and its
                content DOM disables the browser's native spellcheck by default, so the red
                squiggly-underline bug Monaco had doesn't exist here at all. NO own outer border /
                header fill anymore (2026-07-17): the parent pane is now ONE bordered surface with
                `p-6`, so the tool renders INSIDE it — just a plain language label/picker row above
                the editor (`gap-3`), the editor carrying its own themed background + rounded
                corners. */}
            <div className={cn("flex min-h-0 flex-1 flex-col gap-3", tool !== "code" && "hidden")}>
                <div className="flex items-center">
                    {languageItems.length > 1 ? (
                        <Select.Root<{ id: string }, "single">
                            aria-label={t("mockInterview.workspace.languageLabel")}
                            selectedKey={codeState.lang}
                            onSelectionChange={(key) => {
                                if (!key) {
                                    return
                                }
                                const nextLang = String(key)
                                // switching language swaps in that variant's OWN given code
                                // (client-side lookup, no refetch) — not just a re-label of
                                // the same buffer under a different syntax highlighter
                                const variant = givenCodeVariants.find((candidate) => candidate.lang === nextLang)
                                onCodeStateChange({ lang: nextLang, code: variant?.code ?? codeState.code })
                            }}
                        >
                            <Select.Trigger aria-label={t("mockInterview.workspace.languageLabel")} className="w-40">
                                <Select.Value>
                                    {() => <span>{selectedLanguageTitle}</span>}
                                </Select.Value>
                                <Select.Indicator />
                            </Select.Trigger>
                            <Select.Popover>
                                <ListBox.Root aria-label={t("mockInterview.workspace.languageLabel")} items={languageItems}>
                                    {(item) => (
                                        <ListBox.Item key={item.id} id={item.id} textValue={item.title}>
                                            <span>{item.title}</span>
                                        </ListBox.Item>
                                    )}
                                </ListBox.Root>
                            </Select.Popover>
                        </Select.Root>
                    ) : (
                        // exactly 1 authored variant — nothing to SWITCH between, so a picker
                        // would be pure chrome (and, before this fix, the very control that
                        // rendered an untranslated raw i18n key for a non-{ts,java,csharp,go}
                        // language like `dockerfile`). A plain label is honest about there
                        // being one fixed language for this question's given code.
                        <span className="text-sm font-medium text-muted">{displayLangLabel(codeState.lang)}</span>
                    )}
                </div>
                <div className="min-h-0 flex-1 overflow-hidden rounded-xl">
                    <CodeMirror
                        height="100%"
                        theme={theme === "dark" ? vscodeDark : whiteLight}
                        value={codeState.code}
                        extensions={languageExtensionFor(codeState.lang)}
                        onChange={(value) => onCodeStateChange({ ...codeState, code: value })}
                        style={{ height: "100%", fontSize: 14 }}
                    />
                </div>
            </div>
        </div>
    )
}

"use client"

import React, { useState } from "react"
import { TextArea, TextField, Typography, cn } from "@heroui/react"
import { MicrophoneIcon } from "@phosphor-icons/react"
import { Box } from "@/components/frames/Box"
import { StackH, StackV } from "@/components/frames/Stack"

/** How the candidate answers — mirrors the session's `answerMode` (FE-only). */
export type VoiceHeroAnswerMode = "voice" | "text" | "both"

/** Resolved (i18n'd) labels for {@link VoiceHero}. */
export interface VoiceHeroLabels {
    /** Prompt under the idle mic ("Press to answer"). */
    pushToTalk: string
    /** Prompt while listening ("Listening…"). */
    listening: string
    /** Link to switch from voice to typing ("type instead"). */
    typeInstead: string
    /** Link to switch from typing back to voice ("use voice"). */
    useVoice: string
    /** TextArea placeholder. */
    placeholder: string
}

/** Props for {@link VoiceHero}. */
export interface VoiceHeroProps {
    /** Whether speech-to-text is available (falls back to typing when false). */
    sttSupported: boolean
    /** Whether the mic is currently capturing. */
    listening: boolean
    /** In-flight (not-yet-final) transcribed words, shown muted after the draft. */
    interimTranscript: string
    /** The answer draft (voice + typing both land here — owned by the parent). */
    value: string
    /** Update the answer draft (typing). */
    onValueChange: (value: string) => void
    /** Start/stop the mic. */
    onToggleListen: () => void
    /** Which input affordances to show (from setup's "How to answer"). */
    answerMode: VoiceHeroAnswerMode
    /** Resolved labels. */
    labels: VoiceHeroLabels
}

/**
 * The VOICE-FIRST answer composer for the interview room — a big circular
 * push-to-talk mic as the hero (wired to the parent's speech-to-text), with the
 * live transcript building below it and a quiet "type instead" fallback to a text
 * box. Speaking is the signature act of an interview, so the mic leads; typing
 * is the secondary affordance (and the automatic one when the browser has no
 * speech recognition, or when setup picked text-only).
 *
 * @param props - {@link VoiceHeroProps}
 */
export const VoiceHero = ({
    sttSupported,
    listening,
    interimTranscript,
    value,
    onValueChange,
    onToggleListen,
    answerMode,
    labels}: VoiceHeroProps) => {
    // voice is the hero unless setup forced text-only or the browser can't do STT
    const textForced = answerMode === "text" || !sttSupported
    const canToggle = answerMode === "both" && sttSupported
    const [showText, setShowText] = useState(textForced)

    // typing box — used when forced (unsupported / text-only) or toggled to via "type instead"
    if (textForced || showText) {
        return (
            <div>
                <StackV
                    gap={3}
                    principle="sibling-stack"
                    explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                    classNames={["w-full"]}
                    items={[
                        () => (
                            <TextField variant="secondary" className="w-full">
                                <TextArea
                                    rows={4}
                                    value={value}
                                    onChange={(event) => onValueChange(event.target.value)}
                                    placeholder={labels.placeholder}
                                    className="resize-none"
                                    aria-label={labels.placeholder}
                                />
                            </TextField>
                        ),
                        ...(canToggle
                            ? [() => (
                                <button
                                    type="button"
                                    onClick={() => setShowText(false)}
                                    className="group w-fit cursor-pointer text-muted hover:text-foreground"
                                >
                                    {/* Icon+label at preserved 8px — icon-text is step 2 (4px). */}
                                    <StackH
                                        gap={3}
                                        items={[
                                            () => <MicrophoneIcon className="size-4" aria-hidden focusable="false" />,
                                            () => <span className="text-xs font-medium">{labels.useVoice}</span>,
                                        ]}
                                    />
                                </button>
                            )]
                            : []),
                    ]}
                />
            </div>
        )
    }

    // voice hero — big push-to-talk mic + live transcript
    return (
        <div className={""}>
            {/* Mic · prompt · transcript at preserved 12px — no vertical step-4 peer token. */}
            <StackV
                gap={4}
                classNames={["w-full"]}
                items={[
                    () => (
                        <div className="flex w-full flex-col items-center">
                            <button
                                type="button"
                                aria-label={listening ? labels.listening : labels.pushToTalk}
                                aria-pressed={listening}
                                onClick={onToggleListen}
                                className={cn(
                                    "flex size-20 cursor-pointer items-center justify-center rounded-full border-2 transition-colors",
                                    listening
                                        ? "animate-pulse border-danger bg-danger-soft text-danger-soft-foreground"
                                        : "border-accent bg-accent-soft text-accent-soft-foreground hover:bg-accent/15",
                                )}
                            >
                                <MicrophoneIcon className="size-9" aria-hidden focusable="false" />
                            </button>
                        </div>
                    ),
                    () => (
                        <Typography type="body-sm" color="muted" className={cn(listening && "text-danger-soft-foreground")} align="center">
                            {listening ? labels.listening : labels.pushToTalk}
                            {!listening && canToggle ? (
                                <>
                                    {" · "}
                                    <button
                                        type="button"
                                        onClick={() => setShowText(true)}
                                        className="cursor-pointer text-accent-soft-foreground hover:opacity-80"
                                    >
                                        {labels.typeInstead}
                                    </button>
                                </>
                            ) : null}
                        </Typography>
                    ),
                    ...(value || interimTranscript
                        ? [() => (
                            <Box principle="card-padding" className="w-full rounded-2xl bg-default/40 p-4"
                                explain="Card body inset — not page-pad, because this is the surface padding of a card rather than the page chrome.">
                                <Typography className="text-foreground">
                                    {value} <span className="text-muted">{interimTranscript}</span>
                                </Typography>
                            </Box>
                        )]
                        : []),
                ]}
            />
        </div>
    )
}

"use client"

import React from "react"
import { useTranslations } from "next-intl"
import { useSearchParams } from "next/navigation"
import { EnrollGate } from "@/components/blocks/learn/EnrollGate"
import { MockInterviewGatePreview } from "./MockInterviewGatePreview"
import { LearnBreadcrumb } from "@/components/blocks/learn/LearnBreadcrumb"
import { MockInterviewSession } from "./MockInterviewSession"
import { MockInterviewResult } from "./MockInterviewResult"
import { MockInterviewSetupSkeleton } from "./MockInterviewSetupSkeleton"
import { MockInterviewSessionSkeleton } from "./MockInterviewSessionSkeleton"
import { PageHeader } from "@/components/blocks/layout/PageHeader"
import { Container } from "@/components/frames/Container"
import { StackV } from "@/components/frames/Stack"
import { useAppSelector } from "@/redux/hooks"
import { useQueryCourseEnrollmentStatusSwr } from "@/hooks/swr/api/graphql/queries/useQueryCourseEnrollmentStatusSwr"

/** Props for {@link MockInterviewPage}. */
export interface MockInterviewPageProps {
    /**
     * Present when reached via the dedicated `/mock-interview/interview/[sessionId]`
     * route — threaded straight through to {@link MockInterviewSession}, which
     * rehydrates that server-persisted session (24h TTL) instead of showing the
     * green room.
     */
    resumeSessionId?: string
    /** Present on the `/interview/[sessionId]/result` route — shows the graded debrief. */
    resultSessionId?: string
}

/**
 * Mock-interview feature shell: gates the surface behind enrollment (it spends AI
 * credits), and frames the {@link MockInterviewSession} state machine with the
 * standard learn header + breadcrumb.
 *
 * Two shapes, stated as two composed trees rather than one conditional class
 * string: the LIVE interview and the result debrief are full-bleed work surfaces
 * that own their own header, while the green room is a centred reading column.
 *
 * DEBT: `MockInterviewSetupSkeleton` / `MockInterviewSessionSkeleton` are still
 * separate descriptions of the two surfaces below. Folding them in means giving a
 * state machine its own resting state — a change worth reviewing on its own.
 *
 * @param props - {@link MockInterviewPageProps}
 */
export const MockInterviewPage = ({ resumeSessionId, resultSessionId }: MockInterviewPageProps) => {
    const t = useTranslations()
    const courseId = useAppSelector((state) => state.course.entity?.id)
    const courseDisplayId = useAppSelector((state) => state.course.displayId)
    // enrollment status is only ever FETCHED while authenticated (the query's key is
    // disabled otherwise — see `useQueryCourseEnrollmentStatusSwr`), so a guest's
    // `enrollmentSwr.data` stays `undefined` forever; without checking `authenticated`
    // below, `enrollmentResolved` would never flip and the surface would rest forever
    // instead of settling straight into the enroll gate.
    const authenticated = useAppSelector((state) => state.keycloak.authenticated)
    // enrolled-only (spends AI credits) — gate trial viewers behind an enroll CTA
    const enrollmentSwr = useQueryCourseEnrollmentStatusSwr()
    const isEnrolled = enrollmentSwr.data?.courseEnrollmentStatus?.data?.isEnrolled === true
    // during the LIVE interview phase the shell goes full-bleed (course rails dropped via
    // `?phase=interview`); drop the centred measure + page header here to match — the
    // interview is a focused work surface, not a centred reading column. A
    // `resumeSessionId` (the dedicated `/interview/[sessionId]` route) always lands
    // straight in the interview phase, so it counts as live immediately too — no
    // waiting on the query-param mirror to catch up after mount.
    const isLive = useSearchParams().get("phase") === "interview" || Boolean(resumeSessionId)
    // result: its own centred page (like the flashcard quiz result), NOT the full-bleed
    // live shell — but it owns its OWN PageHeader/BackLink internally
    // (`MockInterviewResult`), so it skips this shell's generic header the same way.
    const isResult = Boolean(resultSessionId)
    // resolved once the enrollment check has actually run (nullish, not `!enrollmentSwr.data` —
    // an `{isEnrolled: false}` payload is falsy but IS resolved) — gates the green room /
    // live surface behind its resting state instead of rendering nothing. Guests never
    // fire the query at all, so they resolve immediately (straight to the enroll gate).
    const isSkeleton = !(!authenticated || (enrollmentSwr.data !== undefined && !enrollmentSwr.isLoading))
    const ownsItsHeader = isLive || isResult

    const surface = () => {
        if (isSkeleton) {
            return ownsItsHeader ? <MockInterviewSessionSkeleton /> : <MockInterviewSetupSkeleton />
        }
        if (!isEnrolled) {
            return (
                <EnrollGate
                    title={t("mockInterview.gateTitle")}
                    description={t("mockInterview.gateDescription")}
                    preview={<MockInterviewGatePreview />}
                />
            )
        }
        if (!(courseId && courseDisplayId)) {
            return null
        }
        return resultSessionId ? (
            <MockInterviewResult
                key={courseId}
                sessionId={resultSessionId}
                courseId={courseId}
                courseDisplayId={courseDisplayId}
            />
        ) : (
            <MockInterviewSession
                key={courseId}
                courseId={courseId}
                courseDisplayId={courseDisplayId}
                resumeSessionId={resumeSessionId}
            />
        )
    }

    // full-bleed: the surface below owns its own header and measure
    if (ownsItsHeader) {
        return (
            <StackV
                identity={{ tier: "block", component: "MockInterviewPage" }}
                gap={1}
                body={surface}
            />
        )
    }

    return (
        <Container
            identity={{ tier: "block", component: "MockInterviewPage" }}
            size="md"
            padding={6}
            principle="page-pad"
            explain="Page chrome inset — not card-padding, because this pads the whole page rather than a nested card surface."
            body={() => (
                <StackV
                    gap={7}
                    principle="layout-split"
                    explain="Major layout split — not block-boundary, because this separates primary page regions rather than adjacent blocks."
                    items={[
                        () => (
                            <PageHeader
                                breadcrumb={<LearnBreadcrumb current={t("mockInterview.title")} />}
                                title={t("mockInterview.title")}
                                description={t("mockInterview.subtitle")}
                            />
                        ),
                        surface,
                    ]}
                />
            )}
        />
    )
}
